window.TWHK_DETAILS = {"day-01":{"checked":"2026-11-11","items":{"0":{"title":"Arrive at JFK Terminal 8 (Cathay Pacific Desk)","watch":"Cathay did not publish a T8 counter-closing time on a page that could be read; treat the boarding pass and airport screens as final.","highlights":["Walk times from T8 security to gates: 1–10 about 2–5 min, 12–20 about 2–4 min, 31–41 about 6–12 min, 42–47 about 6–8 min.","T8 lounges: Chelsea, Greenwich and Soho (premium), American Admirals Club; Minute Suites private nap/work suites near Gate 37; Jabbrrbox pods at check-in.","60+ shops and restaurants in T8, many with order-ahead mobile pickup."],"tips":["Cathay online check-in lets you pick seats, store a mobile boarding pass and use self-service bag drop instead of the counter queue.","TWAC (Taiwan arrival card) is free and accepted only within 7 days before arrival; for a Nov 29 landing, file it from about Nov 23 so it is done before you leave home.","Check the live TSA wait shown on the JFK T8 page before leaving home (sampled at 23 min general / 7 min PreCheck on Nov 11)."],"sources":[{"label":"JFK Terminal 8 (Port Authority)","url":"https://www.jfkairport.com/explore-jfk/terminals/terminal-8"},{"label":"JFK T8 lounges and rest","url":"https://www.jfkairport.com/dine-shop-relax/lounge-and-rest?structureName=Terminal+8"},{"label":"Taiwan Arrival Card (National Immigration Agency)","url":"https://twac.immigration.gov.tw/"},{"label":"Cathay Pacific online check-in","url":"https://www.cathaypacific.com/cx/en_US/manage-booking/check-in.html"}]},"1":{"title":"Board Flight CX841 to Hong Kong","hours":"Scheduled 09:00 EST from JFK → 14:05 HKT next day at HKG; 16h05 block.","watch":"PlaneMapper logged 3 delays on CX841 in the prior month (average 154 min). Third-party schedule data — Cathay app/boarding pass is final.","highlights":["Usual equipment recently: Airbus A350-900 (e.g., B-LRD, B-LRK, B-LRI).","In early Nov 2026 most CX841 flights pushed back 09:05–09:30 and several landed at HKG well before 14:05 (12:48–13:59)."],"tips":["An early landing adds slack to the HKG connection; a late one eats into it — check the CX472 gate as soon as you are on the ground.","Note the 09:00 departure applies after the US switch to standard time; October flights left at 10:00 EDT.","Cathay's flight-status tool only covers departures up to 6 days ahead, so live status for Nov 28 appears from about Nov 22."],"sources":[{"label":"PlaneMapper CX841 schedule & history","url":"https://www.planemapper.com/flights/CX841"},{"label":"Cathay Pacific flight status","url":"https://www.cathaypacific.com/cx/en_US/prepare-trip/flight-status.html"}]}}},"day-02":{"checked":"2026-11-11","items":{"0":{"title":"Hong Kong Connection: CX841 Arrival → CX472 Boarding (~1h40 Transit)","getThere":"HKIA transfer with onward boarding pass: follow the directional signs to the Departures level for boarding gates; transfer security screening is mandatory before reaching the gate.","watch":"Do not exit through Arrivals/immigration — that is for entering Hong Kong, not for a same-day connection.","highlights":["Have boarding pass and passport ready before the screening point.","Electronic and metal items in hand baggage go in a separate tray; walk-through metal detector, possible hand search."],"tips":["Liquids sealed in tamper-evident duty-free bags get extra LAGs screening at transfer security and may be unbagged; HKIA advises allowing extra time.","Power banks departing HKG: max two per passenger, carry-on only, and recharging them in flight is prohibited (HKIA notice, 30 Mar 2026)."],"sources":[{"label":"HKIA Transfer / Transit procedures","url":"https://www.hongkongairport.com/en/passenger-guide/transfer-transit/index.page"},{"label":"HKIA power bank notice","url":"https://www.hongkongairport.com/en/important-notice/index.page?noticeid=1585121172788-1"}]},"1":{"title":"Cathay Pacific CX472: Hong Kong → Taipei","hours":"Scheduled 15:45 HKT → 17:35 Taipei; 1h50 block (late-Oct timetable showed 17:40 arrival).","watch":"PlaneMapper logged 8 late departures in the prior month (average 32 min). Third-party data; the Cathay app and boarding pass are final.","highlights":["Usually an Airbus A330-300 on this rotation.","Recent actual departures mostly 16:00–16:50 but arrivals 17:17–18:31 thanks to padding."],"sources":[{"label":"PlaneMapper CX472 schedule & history","url":"https://www.planemapper.com/flights/CX472"}]},"2":{"title":"Touchdown TPE T1: Immigration → Bags → EasyCard → Airport MRT","cost":"Airport MRT A12 Terminal 1 ↔ A1 Taipei Main Station NT$160. Empty EasyCard NT$100 (top-ups NT$100 multiples at machines; any amount at the station information counter).","getThere":"Express train A12 → A1 Taipei Main: 39 min (commuter 53 min). Express and commuter trains alternate about every 7.5 min. Last express to Taipei from A12 departs 22:58.","highlights":["Airport MRT gates also take contactless Visa/Mastercard/JCB/UnionPay and phone wallets at the full single-journey fare.","Taipei Main (A1) connects to the Red (Tamsui-Xinyi), Blue (Bannan) and Green (Songshan-Xindian) lines, TRA and THSR."],"tips":["TWAC must be submitted online within 7 days before arrival; submission is free.","Board the express, not the commuter: 39 vs 53 min to Taipei Main."],"sources":[{"label":"Taoyuan Airport – Airport MRT (fares, times)","url":"https://www.taoyuan-airport.com/airport_mrt?lang=en"},{"label":"Taoyuan Metro – EasyCard","url":"https://www.tymetro.com.tw/tymetro-new/en/_pages/travel-guide/ticketson03.php"},{"label":"Taoyuan Metro – credit card payment","url":"https://www.tymetro.com.tw/tymetro-new/en/_pages/travel-guide/ticketson05.php"},{"label":"Taiwan Arrival Card","url":"https://twac.immigration.gov.tw/"}]},"3":{"title":"Check In: Via Hotel Taipei Station — Bags Down","hours":"Check-in from 15:00; check-out by 12:00.","getThere":"From Taipei Main Station take Exit Z10, then walk about 8 min along Chongqing S. Rd. Sec. 1 to No. 60.","highlights":["Official name: 丰居旅店 北車館 (VIA Hotel Taipei Station), 台北市中正區重慶南路一段60號. Tel +886-2-2314-2121."],"tips":["If you arrive before your room is ready, the hotel will hold luggage so you can head out."],"sources":[{"label":"VIA Hotel Taipei Station FAQ","url":"http://www.vhotel.com.tw/tw/taipei-station/faqs"},{"label":"VIA Hotel Taipei Station official site","url":"https://www.via-hotel.com.tw/taipei-station"}]},"4":{"title":"Fuhong Beef Noodles (backup: Xiao Wu) — Arrival Dinner","hours":"Fuhong: 24 hours, year-round. Xiao Wu: also open 24 hours.","watch":"Prices and payment methods were not found on an authoritative page; bring cash as a fallback.","highlights":["Fuhong (Luoyang St., Ximending edge): rich beef-tallow broth with springy noodles; a late-night canteen for night owls and taxi drivers.","Xiao Wu (same Luoyang St. 'beef noodle war zone'): signature red-braised broth with a distinctive savory edge and soft-stewed beef."],"tips":["Both being 24h means no closing-time pressure tonight — if Fuhong's line is long, walk to Xiao Wu."],"sources":[{"label":"TVBS/女人我最大 via LINE Today (Aug 2026)","url":"https://today.line.me/tw/v3/article/YaRPL78"}]},"6":{"title":"Ximending at Night","hours":"Red House: Sun 11:00–21:00 (free; closed Mondays). Red House creative market (North Plaza): Sun 14:30–21:30, vendors pack up 21:00–21:30.","getThere":"MRT Ximen on the Blue (Bannan) Line; the Red House is about 1 min on foot from Exit 1.","watch":"Red House interior closes 21:00 on Sundays, before this stop starts.","highlights":["Youth-culture hub: street dancing, cosplay, Wannian Plaza accessory shops and the tattoo street.","Red House (1908): one of Taiwan's earliest government-built public markets and the oldest intact Grade-3 heritage market building, at 成都路10號."],"tips":["Arriving 9:30 PM you will see the Red House exterior only; the creative market will be packing up."],"sources":[{"label":"Red House – hours & admission","url":"https://www.redhouse.taipei/contact.aspx"},{"label":"Red House – visit info & MRT","url":"https://www.redhouse.taipei/info.aspx"},{"label":"Red House creative market","url":"https://www.redhouse.taipei/redhouseMarket.aspx?id=1"},{"label":"Taipei Travel – Ximending","url":"https://travel.taipei/en/attraction/details/1694"}]},"7":{"title":"Back to Via Hotel","getThere":"MRT Blue (Bannan) Line from Ximen to Taipei Main Station, exit Z10, then ~8 min walk along Chongqing S. Rd. Sec. 1 to No. 60.","sources":[{"label":"Red House – Ximen station (Bannan Line)","url":"https://www.redhouse.taipei/info.aspx"},{"label":"Taoyuan Airport – Taipei Main Station lines","url":"https://www.taoyuan-airport.com/airport_mrt?lang=en"},{"label":"VIA Hotel Taipei Station FAQ","url":"http://www.vhotel.com.tw/tw/taipei-station/faqs"}]}}},"day-03":{"checked":"2026-11-11","items":{"0":{"title":"Dadaocheng / Dihua Street — Yongle Market, Dry Goods, Tea","hours":"Mon Nov 30: Yongle Market 1F fresh market CLOSED (Monday closure, waived only on lunar 1st/2nd/15th/16th; Nov 30 is lunar 10/22). 2F–3F fabric floors 09:00–18:00 (closed Sundays only), so open on arrival. Wang Tea Dadaocheng shop: Mon–Sat 09:00–18:00.","cost":"Free to browse. Wang Tea factory guided tour (bookable): NT$4,000 per session for up to 20 people, NT$200 each beyond 20; about 20–30 min.","getThere":"MRT Green Line to Beimen (G13, 塔城街10號); Exit 3 (with elevator) is at the SW corner of Tacheng St / Zhengzhou Rd. Yongle Market is at 迪化街一段21號; buses listed by the Taipei Market Administration: 9, Red 25, 206, 250, 255, 274, 302, 660, 669.","watch":"Yongle Market 1F is closed on Mondays. Wang Tea closes Sundays only (open today).","highlights":["Yongle Market (迪化街一段21號): head straight up to 2F–3F, the fabric floors of the building (market dates to 1908; current complex opened 1985).","Wang Tea 有記名茶 (重慶北路二段64巷26號): a working refined-tea factory since c.1947 — shop in front, traditional charcoal-roasting pits and basket-roasting room behind.","Wang Tea range to taste: Wenshan pouchong, high-mountain oolong, Chi Chong oolong, tieguanyin, Oriental Beauty, green and black teas.","Lin Hua Tai Tea 林華泰茶行: founded 1883, one of Taipei's oldest tea merchants; wholesale and retail."],"tips":["With 1F shut there are no market-floor food stalls inside the building today; eat breakfast on the street.","Lin Hua Tai has a single shop and no branches, and warns that imposters online use its name with other addresses and phone numbers.","Fabric-floor phones if you need to check: 2F 02-2558-4858, 3F 02-2558-8846."],"sources":[{"label":"Taipei City Market Administration — Yongle Market","url":"https://www.tcma.gov.taipei/News_Content.aspx?n=1A4C7120ABFD0F9F&sms=26C5BF03E7963F4E&s=C58B40D5621B5A00"},{"label":"Wang Tea — Dadaocheng shop & factory (official)","url":"https://wangtea.com.tw/wangtea-dadaocheng-factory-zh"},{"label":"Taipei Metro — Beimen station","url":"https://web.metro.taipei/pages2026/WebStation/105/1"},{"label":"SME Administration — Lin Hua Tai Tea","url":"https://www.support.sme.gov.tw/lohas/zh-TW/shop/StorePage?a=103&gcid=9337&q=%E6%9E%97%E8%8F%AF%E6%B3%B0%E8%8C%B6%E8%A1%8C"}]},"1":{"title":"Early Lunch — Traditional Dadaocheng / Wanhua Corridor","getThere":"賣麵炎仔 (Mai Mien Yen Tsai, aka 金泉小吃) at 安西街106號, beside the side gate of Yongle Elementary School; from MRT Daqiaotou Exit 1 it is about a 5-minute walk.","watch":"No official website or loadable Michelin page was available to verify hours or prices; food blogs report cash only. Bring cash and confirm opening that morning (phone 02-2557-7087).","highlights":["Signature 紅燒肉: red-fermented pork deep-fried crisp outside, tender inside, served with sweet-chili/soy sauce; it usually appears a little after 9 AM.","湯麵 (plain soup noodles) in a stock of chicken, pork and pork offal.","下水湯 offal soup (liver, heart, kidney) and boiled chicken — order these plus the pork for the protein target, noodles as the side."],"tips":["The menu shows no prices; order with staff at the door, who then seat you.","One reviewer found the dry noodles (乾麵) very salty and recommends the soup noodles instead.","There is a queue most days and it grows toward noon — the 10:00 slot is the right call."],"sources":[{"label":"冰淇淋貓 food blog — 賣麵炎仔 (Oct 2026)","url":"https://icecreamcat.tw/noodleyeh/"},{"label":"水晶安蹄 food blog — 賣麵炎仔 (Apr 2026)","url":"https://auntie.tw/20260109-2/"}]},"3":{"title":"Qingshan Festival — Pass 1 (Main Procession Day)","hours":"Confirmed: Mon Nov 30 2026 = lunar 10/22, the main procession day (正日遶境). Troupes assemble and set off 09:00 from 大理街170巷口; the Lingan Zunwang palanquin departs 11:00. No official end or return time is published.","cost":"Free.","getThere":"MRT Blue (Bannan) Line to Longshan Temple BL10; Exit 1 (elevator) is at Heping W Rd Sec 3 / Xiyuan Rd Sec 1. Qingshan Temple: 貴陽街二段218號. The temple recommends public transport via Longshan Temple station.","watch":"The temple's map shows the procession route, not road-closure times or parking — expect blocked streets and don't rely on cars along it.","highlights":["The Nov 30 route links south and north Wanhua. On the official map, red arrows show troupe direction and green dashed arrows mark troupe assembly stretches.","Ritual order: the Eight Generals (八將, the god's guard) enter the temple to invite him out before the palanquin starts; route placards, regalia, generals and bearers each have set roles.","Main day is the birthday celebration with allied temples and extra troupes; household altars and red stages line the route to receive the god.","Registered Taipei folk cultural heritage (2010) and one of the city's three great temple festivals."],"tips":["To see troupes form up and the palanquin leave, be at the 大理街170巷口 assembly point before 11:00, then shadow the route.","The god's birthday itself is lunar 10/23 = Tue Dec 1; Nov 28 and 29 were the south and north Wanhua night patrols.","The 藝閣 float parade ran only on Nov 28 (19:30) and Nov 29 (19:00) from Hangzhou S Rd — don't expect floats on Nov 30.","Temple phone 02-2382-2296; route text and maps were posted Oct 20 on the temple site and its Facebook page (qingshantemple)."],"sources":[{"label":"媒角抵加 via Yam News — 2026 official route & times","url":"https://n.yam.com/Article/20261021593563"},{"label":"Taipei Travel — 2026 Qingshan event (lunar dates)","url":"https://www.travel.taipei/zh-tw/event-calendar/details/66400"},{"label":"Taipei Civil Affairs festival site — 2026 event","url":"https://www.religiouscarnival.com/edcontent_d.php?lang=tw&tb=8&id=1155"},{"label":"Taipei Metro — Longshan Temple station","url":"https://web.metro.taipei/pages2026/WebStation/085/1"}]},"5":{"title":"Wanhua / Nanjichang Food Break","hours":"Nanjichang (Ln 307–315, Sec 2 Zhonghua Rd) is listed Mon–Sun 06:00–24:00. Open at 3:30 PM Monday: 曉迪筒仔米糕 11:00–22:00 (closed Sat) and 山內雞肉 11:00–21:00 (closed Sat).","cost":"曉迪: braised pork rice NT$35, tube rice cake NT$45, braised pork belly or rib NT$70, trotter NT$90, egg/tofu NT$15, rib soups NT$60. 山內: chicken rice NT$130, thigh rice NT$140, skin-on shank rice NT$120, chicken soup NT$150.","getThere":"The market occupies Lanes 307 to 315 off Sec 2 Zhonghua Rd, Zhongzheng District, at the Wanhua edge.","watch":"Urban renewal: Units 3 and 4 (both sides of Lane 307) are signed; Unit 4 plan submission is expected in H2 2027. Only stalls next to Units 4/5 must move outside hoarding during works. Some shops may still change, so check each stall that day.","highlights":["High-protein order at 曉迪: 滷控肉 or 滷排骨 (NT$70 each) with a braised egg, plus the signature 筒仔米糕.","山內雞肉: whole chickens cooked fresh daily and chilled; boneless tender thigh rice (NT$140) comes with chicken-fat rice and angelica chicken soup.","Nanjichang has six Michelin Bib Gourmand stalls and many family stalls of 30+ years, per the Ministry of Economic Affairs market site."],"tips":["The app's 'Xiaodi rice cake' is 曉迪筒仔米糕 (Xiao Di Tube-Shaped Sticky Rice).","A 2026 report names 臭老闆現蒸臭豆腐 (freshly steamed stinky tofu) among the market's known shops.","Prices are vendor-supplied to the government site; on-site boards prevail."],"sources":[{"label":"MOEA 線上菜市仔 — Nanjichang Night Market","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_detailed/3"},{"label":"MOEA — 曉迪筒仔米糕 hours & menu","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_vendor_detailed/53"},{"label":"MOEA — 山內雞肉 hours & menu","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_vendor_detailed/58"},{"label":"ETtoday — Nanjichang renewal status (Oct 31 2026)","url":"https://house.ettoday.net/news/3263456"}]},"9":{"title":"Qingshan Festival — Pass 3 (Optional, Night)","hours":"No official end time is published for the Nov 30 procession. Backup E7PLAY Sanchong is open 24 hours, every day of the year.","cost":"E7PLAY weekday rate (all day Monday), non-member, per person: 3 h NT$290 if you enter 11:00–23:00 or NT$230 if 23:00–07:00; 5 h NT$330 / NT$270. Add 10% cleaning fee. Overtime NT$30 per 30 min.","getThere":"E7PLAY: B1–B3, 新北市三重區中央南路63號, next to MRT Taipei Bridge station and near Sanhe Night Market; enter the lane at the Shin Kong Bank corner. Taxi there from Wanhua per the plan.","watch":"Bopiliao Historic Block is closed every Monday (street block and indoor exhibits), so it is not an evening fallback. The city arts showcase at Bopiliao and Ximen Exit 6 ran Nov 29 only.","highlights":["One ticket covers bowling (including glow lanes), pool, electronic darts, phone-booth KTV, board games, massage-chair rooms and arcade machines that need no tokens.","Listed arcade titles include Taiko no Tatsujin 14, maimai, Initial D 8, boxing and basketball machines."],"tips":["Bowling: show your ticket at the counter. A lane is set for 30 min and extended in 15-min blocks while lanes are free; if all are full, re-book at the counter.","Darts, massage rooms and KTV need photo ID plus your ticket, so carry passports.","Pay by Visa, Mastercard or JCB card, LINE Pay or TWQR. Outside food is allowed."],"sources":[{"label":"E7PLAY Sanchong — store info & facilities (official)","url":"https://e7play.com.tw/index.php/all-shop/taipei-sanchong/e7play01shop"},{"label":"E7PLAY Sanchong — ticket prices (official)","url":"https://e7play.com.tw/index.php/all-shop/taipei-sanchong/e7play01price"},{"label":"Taipei Dept. of Cultural Affairs — Bopiliao hours","url":"https://culture.gov.taipei/News_Content.aspx?n=0EF5CBADD488A29A&sms=87415A8B9CE81B16&s=E2AB53BBFB12F421"},{"label":"Yilan Cultural Affairs Bureau listing — 2026 Qingshan dates & arts showcase","url":"https://www.ilccb.gov.tw/News_Content.aspx?n=10203&s=410445"}]},"10":{"title":"Wanhua Dinner","hours":"Still open after 22:15 on a Monday at Nanjichang: 好吃鹽水雞 17:00–24:00; 勳章滷味 17:00–23:30 (occasional closures); 八棟圓仔湯 15:00–24:00 (occasional closures). 曉迪 (to 22:00) and 山內 (to 21:00) will already be shut.","cost":"鹽水雞: chicken breast NT$70, leg NT$85, half chicken NT$160. 勳章: beef shank NT$68, beef tendon NT$68, chicken thigh NT$58. 八棟 desserts NT$60–120 (peanut soup NT$75, fermented-rice egg soup NT$65).","getThere":"Same market as the afternoon stop: Lanes 307–315, Sec 2 Zhonghua Rd.","watch":"Stall hours and prices are vendor-supplied to the government site; on-site boards prevail. 龍都 closes at 22:00.","highlights":["Best late protein: 好吃鹽水雞 chicken breast (NT$70), or set 3 — half chicken with six sides (NT$260) to share.","勳章滷味: braised beef shank and tendon, pork shank, chicken thigh; braised without preservatives.","Dessert at 八棟圓仔湯 (since 1977): peanut soup, red-bean mini tangyuan, fermented-rice egg soup, white fungus & lotus seed soup."],"tips":["If you are near Longshan Temple before 22:00, 龍都冰菓專業家 (和平西路3段192號) is open Monday 11:30–22:00 (closed Wednesdays).","Two of these stalls list occasional closures; keep a second option."],"sources":[{"label":"MOEA — 好吃鹽水雞 hours & menu","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_vendor_detailed/54"},{"label":"MOEA — 勳章滷味 hours & menu","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_vendor_detailed/41"},{"label":"MOEA — 八棟圓仔湯 hours & menu","url":"https://serv.gcis.nat.gov.tw/marketyes/website/friendliness_vendor_detailed/44"},{"label":"Wanhua District Office — 龍都冰菓專業家","url":"https://whdo.gov.taipei/News_Content.aspx?n=19CABBEF3F991E9E&sms=FE5F0DE8FA424CE8&s=A3B4BDD97F2079D6"}]},"12":{"title":"Back to Via Hotel","getThere":"Via Hotel Taipei Station, No. 60 Sec 1 Chongqing S Rd. MRT option: Blue Line from Longshan Temple (BL10) 2 stops via Ximen (BL11) to Taipei Main Station (BL12), Exit Z10, then 8–10 min walk along Chongqing S Rd. Or Red Line to NTU Hospital Exit 4, 5–7 min walk through the park.","watch":"Last-train times were not readable on the Metro site; check the Taipei Metro app before relying on the MRT late.","tips":["Hotel phone +886-2-2314-2121.","For a taxi, walk off the procession route first; the official route map is not a road-closure plan."],"sources":[{"label":"Via Hotel Taipei Station — FAQ (official)","url":"https://www.via-hotel.com.tw/taipei-station/faqs"},{"label":"Taipei Metro — Ximen station (BL10–BL11–BL12)","url":"https://web.metro.taipei/pages2026/WebStation/086/1"},{"label":"Taipei Metro — Longshan Temple station","url":"https://web.metro.taipei/pages2026/WebStation/085/1"}]}}},"day-04":{"checked":"2026-11-11","items":{"0":{"title":"Shilin Residence Chrysanthemum Show","hours":"2026 show \"菊映方圓\" runs Nov 27–Dec 13; outdoor exhibition areas 8:00 AM–7:00 PM, so it is open at 8:40 AM on Tue Dec 1. The park itself is open daily year-round 8 AM–6 PM. 2026 indoor-hall hours not yet published (2025: 8:30 AM–5 PM).","cost":"Park and outdoor show: free (no 2026 admission fee announced). The Main Residence building (正館) is separately ticketed, open Tue–Sun 9:30–12:00 and 13:30–17:00.","getThere":"MRT Red Line to Shilin Station Exit 2, turn left, cross Zhongshan N. Rd, ~10 min walk (Parks Office directions). Venue: Shilin Residence Park, 60 Fulin Rd (福林路60號).","watch":"Bloom condition depends on weather and maintenance; zones may be re-routed in rain or wind. Do not step into beds or touch displays. The workshop series was lottery-only (registration closed Oct 31).","highlights":["Theme 菊映方圓: circles, squares and geometric lines worked into flower beds and landscape pieces across 15 themed zones.","Living plant wall designed by green-sculpture artist Lai Wen-bin (26 years' experience), inspired by Henri Matisse, co-planted with Shilin Elementary pupils.","Classic cultivation forms: large standing chrysanthemum (大立菊), cascade (懸崖菊), topiary (造型菊), large and small blooms plus daisy-family bedding."],"tips":["Outdoor zones open at 8 AM, so a weekday 8:40 visit beats the crowds; 35 minutes covers the outdoor loop.","Shoot the whole geometric layout from a distance first, then close-ups; the show is designed for both views.","Arts events are scheduled on weekends/holidays, so expect a quiet show on a Tuesday."],"sources":[{"label":"Taipei Parks Office – 2026 show dates and outdoor hours (Nov 9, 2026)","url":"https://pkl.gov.taipei/News_Content.aspx?n=43E05059FCC72525&sms=72544237BBE4C5F6&s=7ABDE15426ACEC61"},{"label":"Taipei Parks Office – park hours, Main Residence hours (Jan 2026)","url":"https://pkl.gov.taipei/News_Content.aspx?n=43E05059FCC72525&sms=72544237BBE4C5F6&s=0AC2BE10FAD11BEE"},{"label":"Taipei Parks Office – 2025 show release with MRT Exit 2 directions","url":"https://pkl.gov.taipei/News_Content.aspx?n=43E05059FCC72525&sms=72544237BBE4C5F6&s=ADB4C42EA5A0542D"},{"label":"Taipei Travel – 2026 Shilin Residence Chrysanthemum Show","url":"https://www.travel.taipei/zh-tw/event-calendar/details/66398"}]},"1":{"title":"Taxi to Lengshuikeng","hours":"Lengshuikeng Visitor Center: 9:00 AM–4:30 PM; closed the last Monday of each month (Tue Dec 1 is open).","cost":"Taipei taxi meter (day): NT$85 for the first 1.25 km, then NT$5 per 200 m; NT$5 per 60 s when below 5 km/h.","getThere":"Taxi to 冷水坑遊客服務站 (台北市士林區菁山路101巷170號). Public-transport fallback: bus 小15 from MRT Jiantan toward Qingtiangang runs via Lengshuikeng; or Red 5 to Yangmingshan terminal, then the 108 park loop to the 冷水坑服務站 stop.","watch":"Xiaoyoukeng trailhead → Qixing Main Peak (~1.6 km) is fully closed Oct 27, 2026–Jan 19, 2027 (undermined footing ~560 m from Xiaoyoukeng). YMSNP names Lengshuikeng, Menghuan Lake car park and Miaopu as alternative trailheads.","highlights":["Lengshuikeng is a basin between Qixing and Qigu mountains, an old sulphur-mining site.","Milk Lake (牛奶湖): a milky-white pool in the Lengshuikeng explosion crater, seen from a viewing platform on a hillock on the way to the suspension bridge.","Jingshan Suspension Bridge crosses the Lengshuikeng stream, headwater of the Juansi Waterfall."],"tips":["YMSNP runs a live camera at the Lengshuikeng parking lot; check it for fog before leaving Shilin.","108 loop on weekdays: 07:00–17:30, every 30–40 min — fine as a fallback, too slow to rely on for timed plans."],"sources":[{"label":"YMSNP – Qixing Main Peak trail closure notice (Oct 21, 2026)","url":"https://www.ymsnp.gov.tw/ch/titlelist/news/4623"},{"label":"YMSNP – Lengshuikeng (Milk Lake, visitor center hours)","url":"https://www.ymsnp.gov.tw/ch/specialreport/recreation/1115"},{"label":"YMSNP – bus routes (小15, 108, 紅5)","url":"https://www.ymsnp.gov.tw/ch/sglarticle/bus-search-system"},{"label":"Taipei Public Transportation Office – taxi fares","url":"https://pto.gov.taipei/News_Content.aspx?n=6B4D38874E971F4B&sms=87415A8B9CE81B16&s=63C0CCF302898D25"}]},"2":{"title":"Qixing Mountain: Lengshuikeng → East Peak → Main Peak → Lengshuikeng","hours":"Trail has no gate hours; visitor centers (water, info) 9:00 AM–4:30 PM.","cost":"Free.","getThere":"Start at the Lengshuikeng Visitor Center trailhead. Official figures: Xiaoyoukeng→Lengshuikeng 3.7 km / ~2.5 h, of which Xiaoyoukeng→Main Peak 1.65 km and Main↔East Peak 0.3 km (~15 min). So Lengshuikeng→East Peak ≈1.75 km; out-and-back to the Main Peak ≈4.1 km.","watch":"Do not continue from the Main Peak toward Xiaoyoukeng: that 1.6 km section is closed until Jan 19, 2027. Summit is exposed; cancel in fog or high wind.","highlights":["Main Peak ~1,120 m: the highest summit in Yangmingshan National Park.","The name comes from seven igneous-rock knobs left around the old crater after violent eruptions.","East Peak and Main Peak are linked by a 0.3 km saddle walk with up-and-down steps."],"tips":["YMSNP rates the Qixing Main–East Peak trail Grade 2; route junctions are signposted, and the closure notice advises returning the way you came.","Allow the planned 3–3.5 h: ~4.1 km round trip with sustained climbing; turn around by a fixed time to make the ~1:15 PM pickup."],"sources":[{"label":"YMSNP – Qixing Mountain trail system (lengths, times, grade)","url":"https://www.ymsnp.gov.tw/ch/trailpoint/qixing-mountain-range"},{"label":"National Park Service – Qixing Main & East Peak trail segments","url":"https://www.taiwan.nps.gov.tw/home/zh-tw/trails/21197.html"},{"label":"YMSNP – trail closure and alternative trailheads","url":"https://www.ymsnp.gov.tw/ch/titlelist/news/4623"}]},"3":{"title":"Pre-Arranged Pickup at Lengshuikeng → Beitou","cost":"Taxi meter (day): NT$85 first 1.25 km, NT$5 per 200 m, NT$5 per 60 s in slow traffic.","getThere":"Pre-booked taxi from 冷水坑遊客服務站 to Beitou Thermal Valley (地熱谷, 中山路), about 35–40 minutes. Bus fallback (slow): the 108 loop to the Yangmingshan terminal (weekday every 30–40 minutes, last 17:30), then bus 230 down to MRT Beitou.","tips":["Give the driver both the pickup point and 幽雅路30號 in Chinese when booking.","If the taxi fails, the bus fallback is slow: skip Thermal Valley and go straight on to Tamsui."],"sources":[{"label":"Taipei e-bus – route 108 schedule and frequency","url":"https://ebus.gov.taipei/Route/RouteSchedule?routeid=0100010800"},{"label":"YMSNP – bus routes (230 Beitou–Yangmingshan)","url":"https://www.ymsnp.gov.tw/ch/sglarticle/bus-search-system"},{"label":"Taipei Public Transportation Office – taxi fares","url":"https://pto.gov.taipei/News_Content.aspx?n=6B4D38874E971F4B&sms=87415A8B9CE81B16&s=63C0CCF302898D25"}]},"6":{"title":"Taxi to Tamsui","getThere":"Taxi from Xinbeitou MRT straight to Tamsui Old Street, about 30–40 minutes. MRT alternative: Xinbeitou → Beitou on the branch line (3–4 min), then the Red Line north to Tamsui (the terminus).","tips":["On weekdays some Red Line trains run Beitou–Da'an only and start at Beitou heading south; for Tamsui board the northbound platform.","Taxi meter: NT$85 first 1.25 km, NT$5 per 200 m (day rate)."],"sources":[{"label":"Taipei Metro – Tamsui-Xinyi Line routes and headways","url":"https://www.metro.taipei/cp.aspx?n=EAD981369A065968&s=1CC297E1D0B4C7B1"},{"label":"Taipei Public Transportation Office – taxi fares","url":"https://pto.gov.taipei/News_Content.aspx?n=6B4D38874E971F4B&sms=87415A8B9CE81B16&s=63C0CCF302898D25"}]},"7":{"title":"Tamsui — Old Street, Riverfront & Sunset","hours":"Old Street is an open street (listed 24 h). Sunset Tue Dec 1: 5:03 PM; civil dusk ends 5:28 PM (Taipei).","cost":"Free to walk; food pay-as-you-go.","getThere":"From MRT Tamsui Station exit, turn right: Zhongzheng Rd and its extensions Chongjian St and Qingshui St form Tamsui Old Street.","highlights":["Riverside sunset over the Tamsui River mouth; Taipei Travel notes the far end of Old Street opens toward Fisherman's Wharf, a classic sunset spot.","Old Street mixes traditional pastry shops and grocers with snack stalls, clothing and toy shops.","Ferry docks for Bali are along the waterfront (skip per plan)."],"tips":["Be on the riverbank by ~4:50 PM; the best colour runs from the 5:03 sunset to ~5:28 PM dusk.","Walk the waterfront at sunset, then do Old Street and a sit-down dinner after dark."],"sources":[{"label":"New Taipei Travel – Tamsui Old Street","url":"https://newtaipei.travel/zh-tw/attractions/detail/109658"},{"label":"Taipei Travel – Tamsui Old Street","url":"https://www.travel.taipei/en/attraction/details/659"},{"label":"timeanddate – Taipei sunrise/sunset Dec 2026","url":"https://www.timeanddate.com/sun/taiwan/taipei?month=12&year=2026"}]},"9":{"title":"Red Line South to Jiantan","getThere":"Red Line from Tamsui (terminus) southbound to Jiantan; weekday trains ~6 min apart until 19:30, then ~8–10 min. Leave Jiantan by Exit 1 and walk north ~400 m to the Yangming Theater / Shilin Market area.","tips":["Tamsui is the terminus, so every southbound train there passes Jiantan.","The full Tamsui–Guangci run takes ~61 min; Jiantan is well short of that."],"sources":[{"label":"Taipei Metro – Tamsui-Xinyi Line routes and headways","url":"https://www.metro.taipei/cp.aspx?n=EAD981369A065968&s=1CC297E1D0B4C7B1"},{"label":"mm旅遊札記 – Shilin Night Market via Jiantan Exit 1","url":"https://picnicstory.tw/shilin-night-market/"}]},"10":{"title":"Shilin Night Market — Games & Food","hours":"5:00 PM–midnight daily; no market closing day (Taipei Market Office). Individual stalls take their own rest days.","cost":"No entry fee; each stall charges separately.","getThere":"MRT Red Line Jiantan Station. Exit 1 is closest; walk ~400 m north to Yangming Theater and Shilin Market (101 Jihe Rd).","watch":"Mostly cash. Weekend and holiday dinner hours are the most crowded. Keep bags in front in dense lanes.","highlights":["Taipei's largest night market: a triangle around the heritage Shilin Public Market, bounded by Wenlin Rd (east), Jihe Rd (west) and Xiaobei/Xiaoxi St (north).","Two zones: streets around Yangming Theater up to Cixian Temple on Danan Rd, and the Shilin Market building at 101 Jihe Rd.","Protein-forward picks from the official specialties list: big fried chicken cutlet, Shilin sausage, Shanghai pan-fried pork buns, herbal-stewed spare ribs.","Street lanes carry the game stalls and clothing; the market building is for sit-down hot food."],"tips":["Shilin Market B1 food court has ~35 vendors and 600+ seats (steak, xiaolongbao, teppanyaki, oyster omelette) — best base if it rains.","Carry NT$100 notes and coins; some stalls take Taiwanese mobile pay, cards rarely.","Friendly free toilets: Shilin Market and 7-Eleven Wenlin are 24 h."],"sources":[{"label":"Taipei Market Office – Shilin Night Market (hours, area, MRT)","url":"https://www.tcma.gov.taipei/News_Content.aspx?n=FAC14AD2DE4E01A4&s=AF2DC775A3AA076A&sms=32F7BA052C5CA548"},{"label":"Taipei Travel – 士林觀光夜市 (two zones)","url":"https://www.travel.taipei/zh-tw/attraction/details/1536/"},{"label":"Taipei Travel – Shilin Night Market specialties","url":"https://www.travel.taipei/en/attraction/details/1692"},{"label":"mm旅遊札記 – Jiantan Exit 1, B1 food court, payment (checked Oct 20, 2026)","url":"https://picnicstory.tw/shilin-night-market/"}]},"13":{"title":"Back to Via Hotel","cost":"Taxi from 11 PM: night surcharge +NT$20 per trip (flag fall NT$105 for the first 1.25 km), based on boarding time.","getThere":"From Jiantan take the Red Line southbound toward Taipei Main Station (same line, no transfer). After 11 PM Red Line trains run every ~12–15 min. Hotel: 台北市中正區重慶南路一段60號.","tips":["Leaving E7PLAY at ~11:00 PM, a taxi is quicker than the Orange Line plus a transfer."],"sources":[{"label":"Taipei Metro – Tamsui-Xinyi Line headways after 23:00","url":"https://www.metro.taipei/cp.aspx?n=EAD981369A065968&s=1CC297E1D0B4C7B1"},{"label":"Taipei Public Transportation Office – taxi night surcharge","url":"https://pto.gov.taipei/News_Content.aspx?n=6B4D38874E971F4B&sms=87415A8B9CE81B16&s=63C0CCF302898D25"},{"label":"mm旅遊札記 – Red Line Jiantan to Taipei Main Station","url":"https://picnicstory.tw/shilin-night-market/"}]}}},"day-05":{"checked":"2026-11-11","items":{"0":{"title":"Private Driver Pickup at Via Hotel → Shifen","getThere":"Pickup at Via Hotel Taipei Station, No. 60, Sec. 1, Chongqing S. Rd. (台北市中正區重慶南路一段60號), hotel tel +886-2-2314-2121. Destination: Shifen Waterfall Park, 新北市平溪區乾坑10號 (park tel 02-2495-8409).","tips":["Give the driver the Chinese address 新北市平溪區乾坑10號; the park has a visitor centre, toilets and parking.","Nearest listed paid lot: 城市車旅平溪停三, about 526 m from the park — NT$35 first hour, then NT$15 per 30 min, NT$100 daily cap.","Arriving ~9:30 AM is after the 9:00 AM opening, so there is no wait at the gate."],"sources":[{"label":"Via Hotel Taipei Station (official)","url":"https://www.via-hotel.com.tw/taipei-station"},{"label":"New Taipei City Travel — Shifen Waterfall Park","url":"https://newtaipei.travel/zh-tw/attractions/detail/109612"}]},"1":{"title":"Shifen Waterfall Trails & Viewpoints","hours":"Non-summer season (Oct–May): 09:00–17:00, last entry 16:30. (Summer Jun–Sep is 09:00–18:00.)","cost":"Free entry.","getThere":"Driver to 新北市平溪區乾坑10號. From the Shifen visitor centre, walk across 四廣潭橋 (Sihguangtan Bridge) toward the falls.","watch":"Last entry 16:30 in December; irrelevant for a morning visit but matters if the day is reshuffled.","highlights":["Shifen Falls: a curtain-type waterfall on the Keelung River main stream, nicknamed 'Taiwan's Niagara' for its resemblance; the plunge pool below is very deep.","When sun hits the spray a rainbow often appears — look from the lower platforms.","Along the walk from the visitor centre: Sihguangtan pothole formations and Yanjingdong (Spectacles Cave) Falls.","Several viewing platforms: upper ones look onto the green pool at the lip; the lower one gives the full frontal view, the classic photo spot."],"tips":["Budget the full 65 min: the walk out from the visitor centre plus multiple platforms takes longer than the falls alone suggest.","No sky lantern needed — the park itself is the attraction."],"sources":[{"label":"New Taipei City Travel — Shifen Waterfall Park","url":"https://newtaipei.travel/zh-tw/attractions/detail/109612"}]},"2":{"title":"Drive to Jinguashi","getThere":"Gold Museum's official driving route: Freeway 1 toward Keelung → Dahua System IC → Prov. Hwy 62 (Wanrui Expressway) → Ruifang exit → Hwy 2丁 → right on 明燈路 → through Jiufen → North 34 (北34) → Gold Museum. In Google Maps search '黃金博物館遊客服務中心'.","tips":["Parking near the museum is limited; the museum advises using the Quanji Temple (勸濟堂) car park, about a 10-min walk — also the Teapot Mountain trailhead side.","Vehicle controls with shuttle buses apply on national holidays and special-event days only; a Wednesday is normally unaffected.","The mountain road into the museum area takes about 15 min of curves; take motion-sickness precautions."],"sources":[{"label":"Gold Museum — Transport (official)","url":"https://www.gep.ntpc.gov.tw/xmdoc/cont?xsmsid=0G246368749796990112"}]},"3":{"title":"Lunch in Jinguashi — Eat Before the Hike","hours":"Miners' Cafe (礦工食堂): weekdays 09:00–17:00, weekends 09:00–18:00. Gold Museum: Mon–Fri 09:30–17:00 (Wed Dec 2 open).","cost":"Gold Museum admission NT$80 (cash, credit card or O'Pay at the counter; online via the museum's ticket site / Taipei Fun Pass).","getThere":"Miners' Cafe is at 新北市瑞芳區金光路8-1號 (tel 02-2496-2898), inside the Gold Museum park next to No. 8 Jinguang Rd.","watch":"Museum closed on the first Monday of each month (Dec 7, 2026), Lunar New Year's Eve/Day and government natural-disaster closure days. Dec 2 (Wed) is not a closure day.","highlights":["Miners' Cafe is the site of the miners' lunch box (礦工便當) referenced in the notes; it also sells sweet-potato soft serve made from Tainung No. 18 sweet potato.","If time allows after eating: the museum park itself is the rain backup for the hike."],"tips":["Eat at the cafe, not in the museum: eating, drinking and gum are banned inside museum buildings.","Gold-panning experience was suspended Oct 5–Nov 30, 2026 for roof works; the notice runs to Dec 1, so confirm on arrival before planning around it."],"sources":[{"label":"New Taipei City Travel — Miners' Cafe","url":"https://newtaipei.travel/zh-tw/shop/detail/207452"},{"label":"Gold Museum — Tickets & Hours (official, zh)","url":"https://www.gep.ntpc.gov.tw/xmdoc/cont?xsmsid=0G246368552167800609"},{"label":"Gold Museum — Admission & Opening Hours (official, en)","url":"https://www.gep-en.ntpc.gov.tw/xmdoc/cont?xsmsid=0N245407682332344267"},{"label":"Gold Museum — gold-panning suspension notice","url":"https://www.gep.ntpc.gov.tw/xceventsnews/cont?xsmsid=0G266496700270752519&sid=0Q254403485632857841"}]},"4":{"title":"Teapot Mountain / Jinguashi Mining Landscape","hours":"Open 24 hours.","cost":"Free.","getThere":"Trailhead reachable from either the Gold Museum or Quanji Temple (勸濟堂); the official listing gives the route as about 1.16 km. Hiker reports: ~10 min from Quanji Temple to the trailhead, then stone steps to a mid-slope viewpoint and the 'teapot mouth'.","watch":"The teapot-mouth scramble needs hands and feet; skip it if rock is wet. Steps get slippery in rain, and winter brings northeast-monsoon wind and fog — turn back at the lower viewpoint if visibility goes.","highlights":["Teapot Mountain (無耳茶壺山), ~600 m elevation, named for its handleless-teapot summit as seen from Jinguashi.","Summit views: the Pacific to the east, Banping Mountain to the south, Keelung Mountain and the coastal road, and the blue-yellow Yin-Yang Sea below.","The 'teapot mouth' at the top: a rock opening you climb into and out the other side — the signature photo spot."],"tips":["Official grade: 'natural hiking' (stone and timber surfacing) with alternating climbs and flats; strenuous for unfit walkers but easy for this group.","Hiker reports put the ascent at 40–60 min and descent 30–40 min, which fits the 2-hour block with summit time.","There is no water or food on the trail; carry at least 500 ml each."],"sources":[{"label":"New Taipei City Travel — Teapot Mountain Trail","url":"https://newtaipei.travel/zh-tw/attractions/detail/109986"},{"label":"Hiking Biji — Teapot Mountain trail report (corroboration)","url":"https://hiking.biji.co/index.php?q=review&act=info&review_id=37685"}]},"5":{"title":"Golden Waterfall & Yin-Yang Sea (Photo Stops, If on Route)","hours":"Both open 24 hours / year-round.","cost":"Free.","getThere":"Both sit on the Shuinandong coastal side reached via North 34 (北34) from the Gold Museum: Golden Waterfall is beside 金水公路; Yin-Yang Sea is just north of Shuinandong village. The museum lists Hwy 2 km 78.5 (Shuinandong car park) ↔ North 34 as its coast-side road.","watch":"These are downhill toward the coast from the museum, not on the direct Jinguashi→Jiufen road; adding them means a descent and climb back on North 34. Drop them first if behind schedule.","highlights":["Golden Waterfall: water pouring over rocks stained gold by iron-sulfide minerals leached by the area's heavy rain; the streambed is golden along the approach.","Yin-Yang Sea: a bay with a sharp blue/yellow-brown split, caused by iron hydroxide from pyrite weathering on Jinguashi Mountain."],"tips":["Parking: Shuinandong car park is ~133 m from the Yin-Yang Sea viewpoint; the Shuinandong visitor-centre lot is ~524 m from Golden Waterfall.","Both are drive-up photo stops; 10 minutes each is enough."],"sources":[{"label":"New Taipei City Travel — Golden Waterfall","url":"https://newtaipei.travel/zh-tw/attractions/detail/110626"},{"label":"New Taipei City Travel — Yin-Yang Sea","url":"https://newtaipei.travel/zh-tw/attractions/detail/109992"},{"label":"Gold Museum — Transport (official)","url":"https://www.gep.ntpc.gov.tw/xmdoc/cont?xsmsid=0G246368749796990112"}]},"6":{"title":"Jiufen — Hillside Lanes, Food, Views, Dusk","hours":"Jiufen Old Street (基山街) listed hours: Mon–Thu 08:00–19:00, Fri–Sun 08:00–22:00 (Wed Dec 2: until 19:00). Sunset Dec 2 in Taipei: 5:03 PM; civil twilight ends 5:28 PM.","cost":"Free to walk. Nearby lot 禾亭-九份礦業 (~159 m): NT$200 per entry.","getThere":"Driver to 新北市瑞芳區基山街 (Jiufen Old Street); bus stop, toilets and parking are listed at the street.","highlights":["Classic snacks named by the city: taro balls (芋圓), meatballs (肉圓) and 草仔粿 (herb rice cakes).","Shengping Theater (昇平戲院), Jiufen's first theatre, with a vintage ticket booth, old film posters and kiosk.","The film location of 'A City of Sadness'; the red lanterns and hillside lights at dusk are the main event."],"tips":["Sunset is 5:03 PM, after you leave at 4:00 PM, so plan on daytime sea views from the upper lanes rather than dusk.","On a weekday the street winds down at 19:00, so eat snacks early rather than saving them for after dark."],"sources":[{"label":"New Taipei City Travel — Jiufen Old Street","url":"https://newtaipei.travel/zh-tw/attractions/detail/109990"},{"label":"timeanddate — Taipei sunrise/sunset Dec 2026","url":"https://www.timeanddate.com/sun/taiwan/taipei?month=12&year=2026"}]},"7":{"title":"Private Driver Back to Taipei","getThere":"Either to Via Hotel Taipei Station (台北市中正區重慶南路一段60號) or straight to the Da'an area near NARA (台北市大安區仁愛路四段345巷4弄19號), which is a 6-min walk from MRT Zhongxiao Dunhua.","tips":["Dropping straight in Da'an saves a cross-city return: NARA is 6 min from Zhongxiao Dunhua and 10 min from Xinyi Anhe or Sun Yat-sen Memorial Hall MRT.","If Jiufen traffic runs late, skip the hotel: NARA holds the 8:30 PM slot for only 10 minutes."],"sources":[{"label":"Via Hotel Taipei Station (official)","url":"https://www.via-hotel.com.tw/taipei-station"},{"label":"FunNow — NARA Thai Massage branch page","url":"https://www.myfunnow.com/en/branches/3027568833955"}]},"10":{"title":"NARA Thai Massage: 120-min Traditional Bodywork","cost":"FunNow '泰式古法舒壓按摩 120 min': from TWD 1,299 (listed TWD 1,400). Thai oil massage 120 min: from TWD 1,599. Prices vary by slot.","getThere":"No. 19, Aly. 4, Ln. 345, Sec. 4, Ren'ai Rd., Da'an (台北市大安區仁愛路四段345巷4弄19號), beside 東區粉圓. MRT Zhongxiao Dunhua 6 min walk; Xinyi Anhe or Sun Yat-sen Memorial Hall 10 min. Tel 02-2771-6692.","watch":"This package cannot specify a particular therapist or therapist gender. Arrive on time: 10-minute hold, then possible cancellation without refund.","highlights":["Package: 10-min foot bath + 110-min traditional Thai massage + snack and tea (110 min of hands-on time).","All therapists are Thai women; handmade Thai dessert after the session (limited daily; substituted if sold out).","Private rooms, shower and Wi-Fi listed; rated 4.9 on FunNow (6,800+ reviews)."],"tips":["Book in the FunNow app/site; the earliest bookable slot is 10:00, so an 8:30 PM slot should be reserved in advance.","Tell staff about any injury or sensitive areas before starting; pressure is checked during the session per reviews."],"sources":[{"label":"FunNow — NARA 120-min traditional Thai massage","url":"https://www.myfunnow.com/zh-tw/products/3050385552931"},{"label":"FunNow — NARA Thai Massage branch page","url":"https://www.myfunnow.com/en/branches/3027568833955"},{"label":"i-formosa — NARA listing (address, phone)","url":"https://i-formosa.com/places/narathai/"}]},"11":{"title":"East District Late Food & Dessert","hours":"Eastern Ice Store 東區粉圓: open daily 11:00–23:00 (open all year).","cost":"One flat price per bowl with up to 4 toppings — NT$70 per the most recent blog update (an older guide lists NT$60). Free self-serve ice and syrup top-ups.","getThere":"東區粉圓, 台北市大安區忠孝東路四段216巷38號 — right next to NARA. MRT Zhongxiao Dunhua Exit 3.","watch":"Eastern Ice closes at 23:00, so the second half of the 10:30–11:30 PM block needs another late venue; none was verified for this item.","highlights":["Handmade tapioca pearls plus ~30 toppings: taro, sweet-potato balls, red bean, grass jelly, tofu pudding, peanuts, aiyu jelly, coix seed.","The East District is Taipei's designated night-life hub ('五夜城'), with lanes of late eateries around Zhongxiao Dunhua."],"tips":["Go straight from NARA: you finish at ~10:30 PM and the shop closes at 23:00. Order by pointing at the trays; a queue moves fast.","Taro and peanut toppings are already very sweet — skip extra syrup."],"sources":[{"label":"東區粉圓 official site — location/transport","url":"https://efy.com.tw/travel.html"},{"label":"Taipei Travel Geek — Eastern Ice Store","url":"https://www.taipeitravelgeek.com/eastern-ice-store"},{"label":"SaraTrip — 東區粉圓 (hours, price)","url":"https://saratrip.com/eastern-ice/"},{"label":"Taipei Travel — East District shopping area","url":"https://www.travel.taipei/zh-tw/attraction/details/1981"}]},"12":{"title":"Back to Via Hotel","getThere":"Taxi from Zhongxiao Dunhua / Ren'ai Rd area to Via Hotel Taipei Station, No. 60, Sec. 1, Chongqing S. Rd. (台北市中正區重慶南路一段60號). Show the driver the Chinese address.","tips":["Hotel phone for the driver if needed: +886-2-2314-2121.","The nearest MRT for an alternative is Zhongxiao Dunhua on the Bannan Line (Exit 3 is the Eastern Ice exit)."],"sources":[{"label":"Via Hotel Taipei Station (official)","url":"https://www.via-hotel.com.tw/taipei-station"},{"label":"東區粉圓 official site — location/transport","url":"https://efy.com.tw/travel.html"}]}}},"day-06":{"checked":"2026-11-11","items":{"0":{"title":"Zhongzheng Sports Center — Archery","hours":"9:00 AM – 10:00 PM; 6:00–9:00 AM by reservation only","cost":"NT$300 for the first hour, including range, bow, equipment and basic instruction","getThere":"臺北市中正運動中心, 台北市中正區信義路1段1號 (tel 02-2396-1000). The archery range is on 9F, across Xinyi Rd from Chiang Kai-shek Memorial Hall, near MRT Chiang Kai-shek Memorial Hall station.","watch":"ID and age rules for the range weren't stated; bring your passports.","highlights":["Indoor 30 m range with 12 parallel target lanes and backstop netting on the building's 9F.","Walk-in flow reported: register and pay at the 9F range counter; lanes are assigned as they free up, so expect a short wait at peak times.","Shooters must follow the range officer's commands for shooting and arrow retrieval."],"tips":["First-timers get a 10–15 minute safety and basic-technique briefing.","The centre is run by 舞動陽光 (wsjjsc.com.tw); phone 02-2396-1000 if plans change."],"sources":[{"label":"iPlay national sports venue registry (Sports Administration)","url":"https://iplay.sports.gov.tw/GymInfo/Index/9627"},{"label":"Blog: Zhongzheng Sports Center archery range","url":"https://www.lovefood.cc/2024/09/1300-tpejjsports.html"},{"label":"Old operator Facebook page (now 舊營業者)","url":"https://www.facebook.com/tpejjsports/"}]},"1":{"title":"Liberty Square / Chiang Kai-shek Memorial Hall — Quick Pass","hours":"Memorial Hall 9:00 AM–6:00 PM daily; Memorial Park 5:00 AM–midnight.","cost":"Free.","getThere":"No. 21 Zhongshan S. Rd. MRT Chiang Kai-shek Memorial Hall station (Red Tamsui-Xinyi and Green Songshan-Xindian lines): about 8 min on foot from Exit 3, 9 min from Exit 5. Dongmen station (Orange) Exit 3 is also about 8 min.","watch":"Drills are cancelled when it rains. The hall closes on Lunar New Year's Eve/Day, 228 Peace Memorial Day and maintenance days (not an issue on Dec 3).","highlights":["Military Honor Guard Ceremonial Patrols and Drills run hourly 9:00 AM–5:00 PM (about 15 min each) on Democracy Boulevard in front of the hall stairs; the 11:00 AM drill fits this slot.","6.3 m bronze statue inside the main hall; the 25-hectare complex was completed in 1980.","Free exhibitions are running in the hall in late 2026, but this stop is a quick pass."],"tips":["Arrive by about 10:55 AM and stand near the hall stairs to catch the 11:00 AM drill before lunch.","Flag lowering is 5:10 PM (Oct 1–Mar 31) if you ever pass back through at dusk."],"sources":[{"label":"CKS Memorial Hall – Visit Info","url":"https://www.cksmh.gov.tw/en/cp.aspx?n=6369"},{"label":"CKS Memorial Hall – Transportation","url":"https://www.cksmh.gov.tw/en/cp.aspx?n=6422"}]},"2":{"title":"Light Early Lunch — Jin Feng Braised Pork Rice","getThere":"金峰魯肉飯, 台北市羅斯福路一段10號之1, beside Nanmen Market; MRT Chiang Kai-shek Memorial Hall station Exit 2. Tel (02) 2396-0808.","watch":"No official site; blogs disagree on hours (09:00–01:00 daily vs 11:00–01:00 closed Monday), so confirm on Google Maps. Thursday is open under both.","highlights":["Braised pork rice in small/medium/large: hand-cut, fatty, gelatinous pork with pickled cucumber.","Protein add-ons: braised duck egg, fried tofu, braised pork belly (焢肉), pork thick soup (肉羹湯), chicken soups.","Also sells 鼎邊趖 (rice-batter soup with shrimp and pork), rare in Taipei."],"tips":["Dine-in: scan the table QR code (Chinese/English/Japanese menu with photos), order, eat, then pay at the counter. Takeaway: scan, pay first, then wait.","Since Feb 2025 the left storefront is gone; most seating is now upstairs on 2F with only a few tables at the back of 1F.","Turnover is fast; a weekend-noon queue was 20–30 min, so a weekday 11:05 AM arrival should be quicker."],"sources":[{"label":"Blog (updated 2025-11-19): Jin Feng","url":"https://lordcat.net/archives/2247"},{"label":"Blog: Jin Feng menu and QR ordering","url":"https://panpanlife.com/jinfeng/"}]},"4":{"title":"10m Air-Rifle Shooting — Zhongzheng Sports Center","hours":"Monday closed; Tue–Fri 1:00–9:00 PM; Sat 10:00 AM – 9:00 PM; Sun 10:00 AM – 6:00 PM","cost":"NT$350 per person per session, including the gun, coaching, one target and 30 pellets","getThere":"Back to 台北市中正區信義路1段1號. The 10 m air-gun range is on 6F; earlier operator rules were to buy the ticket at the 1F counter first, then go up to 6F.","highlights":["Indoor 10 m air-gun range with 10 international-standard fixed lanes and electronic target carriers.","Coaches give a safety briefing, explain the gun and loading, and teach a two-handed hold for beginners.","One of only two Taipei City sports centres with an indoor shooting range."],"tips":["Arrive at 1:00 PM sharp on a Thursday to get an early lane.","Call 02-2396-1000 only if plans change."],"sources":[{"label":"Blog: Zhongzheng 10M shooting range","url":"https://fgblog.fashionguide.com.tw/11633/posts/417123"},{"label":"iPlay national sports venue registry (Sports Administration)","url":"https://iplay.sports.gov.tw/GymInfo/Index/9627"}]},"5":{"title":"Taipei 101 Observatory (89F)","hours":"Daily 10:00 AM–9:00 PM; last admission 8:15 PM.","cost":"General ticket (89F + 88F): adult NT$600; concession NT$540 (children over 115 cm, students, special needs); Priority Pass NT$1,200; under 115 cm free. Visiting 101F costs NT$380 more per person. Skyline 460 (outdoor 101F) is NT$3,000 by reservation.","getThere":"MRT Red line direct from Chiang Kai-shek Memorial Hall to Taipei 101/World Trade Center station. Go to the Observatory Ticket Counter on the Office Tower 1F (temporary arrangement 2026/6/1–12/25).","watch":"Concession tickets need a valid Taiwan ID, so foreign adults pay NT$600. Skyline 460 requires height over 145 cm and no heels or skirts, and is cancelled in bad weather.","highlights":["382 m-high 89F deck with a 360° view of Taipei.","Elevators climb up to 1,010 m/min: 37 s from 5F to 89F.","The 660-tonne, 5.5 m tuned mass damper ball, the world's largest on public display.","Photo zones: Infinite Horizon kaleidoscope, Secret Garden in the Clouds, Rainbow Light Zone."],"tips":["Full-price tickets can be bought online; concession tickets are sold only at the Office Tower 1F counter.","The 'Taipei 101 Observatory & Taipei Metro' combo is NT$990: observatory ticket plus a collectible EasyCard that works as a Metro one-day pass with NT$150 preloaded. Buy via Taipei FunPASS or KLOOK; redeem at Taipei Main or Taipei 101/World Trade Center station."],"sources":[{"label":"Taipei 101 – Observatory","url":"https://www.taipei-101.com.tw/en/observatory"},{"label":"Taipei 101 – Ticket Information (EN)","url":"https://www.taipei-101.com.tw/en/observatory/ticket"},{"label":"Taipei 101 – 購票資訊 (ZH)","url":"https://www.taipei-101.com.tw/tw/observatory/ticket"},{"label":"Taipei Metro – 101 combo ticket news","url":"https://english.metro.taipei/News_Content.aspx?n=840A770A8CA5AB80&sms=DFFA119D1FD5602C&s=36F8B07276E5AE50"}]},"6":{"title":"Elephant Mountain — Golden Hour & Dusk","cost":"Free.","getThere":"MRT Xiangshan station Exit 2, then through Xiangshan Park and Lane 150, Xinyi Rd Sec 5. The sign there reads 'Elephant Mountain Trail (Lingyun Temple) 700 m, about 10 min'. The trailhead is at the end of Lane 150, Alley 22, next to Daitian Temple/Lingyun Temple 靈雲宮.","watch":"Official PWD notice: partial trail closures for upgrade works from 2026-07-20 to 2027-04-13. On-site detour maps showed one section closed until 2026-12-20 and another until 2027-02-28; the photo platform 攝手平台 area is affected. Detours are paved stone steps.","highlights":["Peak 183 m; the trail is 1,450 m long and about 1 h 40 min end to end.","Stone steps all the way, with railings at drops and handrails on steep pitches. Yongchun Pavilion (toilets and AED) is the midway rest stop.","Six Giant Rocks viewing platform faces Taipei 101; it is about 19 min more to Xiangshan Peak, which has a heart-shaped bench framing 101.","Toilets at Lingyun Temple, near Yongchun Pavilion and at Yixian Pavilion near the peak."],"tips":["A September 2026 walk took about 14 min from Exit 2 to the trailhead, 49 min to Six Giant Rocks and 68 min to the peak, including photo stops.","If the 2026 entrance works are underway, the original trailhead is closed 8:00 AM–5:00 PM; enter via Lingyun Temple and follow the in-temple 象山登山步道入口 signs.","Do not climb the giant rocks; the posted rule is no climbing, and the platform has the full 101 view."],"sources":[{"label":"Taipei Public Works Dept – trail closure notice","url":"https://pwd.gov.taipei/News_Content.aspx?n=C8255DF7355DF2F1&s=8826D23D548E4171"},{"label":"Taipei Travel – 象山親山步道","url":"https://www.travel.taipei/zh-tw/attraction/details/185"},{"label":"Blog: Elephant Mountain walk, Sep 2026","url":"https://zanzan.tw/archives/a00022"}]},"7":{"title":"Raohe Night Market","hours":"Daily 5:00 PM–midnight (individual stalls vary).","getThere":"MRT Songshan station (Green Songshan-Xindian line, terminus) Exit 5, about 1 min to the gate beside Songshan Ciyou Temple. Houshanpi (Blue) is the alternative. Raohe St. between Sec. 4 Bade Rd and Fuyuan St.","watch":"Taipei Travel lists Ciyou Temple closing at 22:30, so visit the temple before late-night eating.","highlights":["Fuzhou pepper buns 福州世祖胡椒餅 (Michelin Bib Gourmand), right at the Ciyou Temple gate in front of No. 249: charcoal-baked on drum-oven walls, filled with black-pepper pork and scallion.","Chen Dong herbal pork ribs 陳董藥燉排骨 (Bib Gourmand, No. 160): falls-off-the-bone ribs in a medicinal-herb broth, topped with ginger; pair with braised pork rice.","Shi Boss spicy stinky tofu with duck blood (Bib) and Ma Shu Bao Bao mochi (peanut, sugar or black sesame).","Songshan Ciyou Temple (31 m) and Rainbow Bridge (109 m, open 24 h) are next to the market."],"tips":["Michelin says the pepper-bun line moves fast; it is at the entrance, so join it first.","Thursday is clear of the regular stall rest days FUNIT lists (Chen Dong closes Tue; A-Guo lu wei and Ma Shu Bao Bao Mon; 身煎百戰 Wed).","More protein: big fried chicken cutlet 小師傅大雞排 (opposite No. 192), beef noodles and beef offal soup (in front of No. 63)."],"sources":[{"label":"Taipei Travel – Raohe Street Tourist Night Market","url":"https://www.travel.taipei/en/attraction/details/1691"},{"label":"MICHELIN Guide – 5 Michelin-Recommended Eats at Raohe","url":"https://guide.michelin.com/en/article/travel/5-michelin-recommended-eats-at-taipei-raohe-night-market"},{"label":"FUNIT Raohe stall guide (updated 2026-11-10)","url":"https://gofunit.com/%E9%A5%92%E6%B2%B3%E5%A4%9C%E5%B8%82%E7%BE%8E%E9%A3%9F/"}]},"9":{"title":"Taipei Christmas — Opening Night","hours":"Event runs Dec 3, 2026–Jan 1, 2027 (Dec 3 is the opening day). Daily lighting and concert times were not yet published on 2026-11-11.","cost":"Free public event.","getThere":"Daan Forest Park, 臺北市大安區新生南路二段1號. Nearby parking: Jianguo S. Rd viaduct lots (165–271 m) and the Daan Forest Park underground car park (265 m).","watch":"Opening-night timings, stage location and any crowd controls are not yet published.","highlights":["'2026臺北耶誕愛無限' organised by Taipei's Department of Information and Tourism: light installations across Daan Forest Park.","A '耶誕音樂會' Christmas concert with several singers is part of the programme."],"tips":["This is the Taipei City event. New Taipei's 新北歡樂耶誕城 (christmasland.ntpc.gov.tw, Banqiao) is a separate event; its site showed '2 天後開城' on 2026-11-11.","Recheck the Taipei Travel event page a few days before for the opening-night concert time and line-up."],"sources":[{"label":"Taipei Travel – 2026臺北耶誕愛無限","url":"https://www.travel.taipei/zh-tw/event-calendar/details/66401"},{"label":"New Taipei Christmasland official site","url":"https://christmasland.ntpc.gov.tw/"}]},"12":{"title":"Back to Via Hotel","getThere":"From the market, MRT Songshan station (Green Songshan-Xindian line) by the Ciyou Temple end, or a taxi to 台北市中正區重慶南路一段60號.","tips":["If using the 101 + Metro combo EasyCard, its one-day pass is valid until the end of Metro operations that day.","At 11:30 PM check the last-train time in the Go! Taipei Metro app or the metro.taipei 'First & Last Trains' page; take a taxi if it is tight."],"sources":[{"label":"Taipei Travel – Raohe (nearby MRT)","url":"https://www.travel.taipei/en/attraction/details/1691"},{"label":"Taipei Metro – combo ticket / one-day pass terms","url":"https://english.metro.taipei/News_Content.aspx?n=840A770A8CA5AB80&sms=DFFA119D1FD5602C&s=36F8B07276E5AE50"}]}}},"day-07":{"checked":"2026-11-11","items":{"0":{"title":"Checkout → Taipei Main → THSR Boarding","hours":"THSR Taipei Station: operation 06:00–24:00; ticketing 06:00 until last train departure","getThere":"THSR Taipei Station is at No.3 Beiping W. Rd. (Zhongzheng). It links by B1/B3 corridors to the TRA Taipei Station gate areas; follow THSR signs down to the THSR concourse and gates.","watch":"Reserved tickets are valid only for the date and train number printed; miss it and you lose the seat.","highlights":["Pick up or check the reserved ticket before 8:45; trains in this window leave at 08:31, 08:46 and 09:01 (Dec 4 timetable).","Carry-on limit per piece: ≤150 cm long and ≤220 cm length+width+height; 40 kg total per passenger."],"tips":["Large suitcases go in the luggage area at the car ends; small bags on the rack above window seats.","No hot/cold drinking water is provided on board — buy water before the gates."],"sources":[{"label":"THSR Taipei Station info","url":"https://en.thsrc.com.tw/ArticleContent/53156954-1528-461f-af8b-54c517a435a4"},{"label":"THSR Passenger Guide (baggage limits)","url":"https://en.thsrc.com.tw/ArticleContent/0ab9938f-60c9-4ca0-b91d-7d9b90ea155a"},{"label":"THSR services overview (water, lockers)","url":"https://www.thsrc.com.tw/ArticleContent/9915abee-dc70-4ba3-9f6d-c425873c3475"}]},"1":{"title":"THSR: Taipei → Zuoying","hours":"Fri Dec 4 southbound Taipei→Zuoying: 0207 08:31→10:10 · 0615 08:46→10:45 · 1307 09:01→11:00 · 0813 09:11→11:25 · 0619 09:21→11:20 · 0117 09:31→11:05","cost":"Standard reserved NT$1,490 · Non-reserved NT$1,445 · Business NT$2,440 (adult, one way)","getThere":"Non-reserved cars are 10–12 on most of these trains (9–12 on 0615). Car 6 is the Business Car. 0117 (09:31) is the fastest at 1h34 and still arrives 11:05.","watch":"Non-reserved tickets are valid for the date but do not guarantee a seat. Do not eat strong-smelling food on board.","highlights":["0615 (08:46→10:45) or 1307 (09:01→11:00) match the plan; 0207 (08:31→10:10) buys an extra 50 min in Zuoying.","Every car has at least one large-luggage area by the doors.","Toilets in cars 1/3/5/7/9/11; cold-drink vending in cars 1, 5 and 11."],"tips":["Standard-car seats swivel 180° so a group can face each other.","Early-bird discount was showing on train 0813 at time of check; discounts are capped and change — check the booking system."],"sources":[{"label":"THSR timetable & fare search (Dec 4 query)","url":"https://www.thsrc.com.tw/ArticleContent/a3b630bb-1066-4352-a1ef-58c7b4e8ef7c"},{"label":"THSR car services","url":"https://en.thsrc.com.tw/ArticleContent/5e3b8b4d-ca1e-447d-b95b-fd7e4e5cccda"},{"label":"THSR Passenger Guide","url":"https://en.thsrc.com.tw/ArticleContent/0ab9938f-60c9-4ca0-b91d-7d9b90ea155a"}]},"2":{"title":"Store Luggage at New Zuoying","hours":"THSR Zuoying Station operation 05:25–24:00","getThere":"THSR Zuoying Station, No.105 Gaotie Rd. The 2F corridor links to TRA Xinzuoying Station; Global Mall (Boulder Space, 3F) occupies 1–4F of the Xinzuoying station building at 站前北路1號.","watch":"Locker prices and sizes are not published on the THSR site; large suitcases may not fit small lockers — have a fallback (hotel can't take bags until it is open to you).","highlights":["THSR runs paid coin lockers (寄物櫃) at every station; the Zuoying floor map lists a Baggage Storage point.","Storing here keeps bags beside the climbing gym, which is in the same station complex."],"tips":["Use the station floor map (1F/2F) on the THSR Zuoying page to find the locker bank before you arrive.","Global Mall 2F food hall: some counters from 07:30, restaurants from 11:00 — handy for a snack while sorting bags."],"sources":[{"label":"THSR Zuoying Station info","url":"https://en.thsrc.com.tw/ArticleContent/ecdd8e68-3d12-4f0f-8385-f4891e513494"},{"label":"THSR services overview (寄物櫃)","url":"https://www.thsrc.com.tw/ArticleContent/9915abee-dc70-4ba3-9f6d-c425873c3475"},{"label":"Global Mall Xinzuoying branch info","url":"https://www.twglobalmall.com/branch/7/8"}]},"3":{"title":"Lunch at Zuoying — Fenyang Wonton (Founding Shop)","getThere":"高雄市左營區左營大路84號 (old Zuoying) — this is not inside the station complex (高鐵路105號 / 站前北路1號); budget a taxi each way.","watch":"Opening hours for the founding shop are not published by the operator; branch hours differ (e.g. 德賢店 11:00–23:00).","highlights":["This address is the founding shop of 老左營汾陽餛飩 (opened 1954), tel 07-588-7000.","Order the hand-wrapped wontons: fresh pork hind-leg filling, made by hand daily.","Add 祖傳鹹湯圓 — savoury glutinous dumplings filled with pork and shiitake."],"tips":["Wonton soup plus salty tangyuan is a solid pre-climb protein lunch.","Call ahead (07-588-7000) to confirm it is open Friday lunchtime — hours are not on the official site."],"sources":[{"label":"老左營汾陽餛飩 official site","url":"https://fywonton.com.tw/"},{"label":"Official site: founding shop address","url":"https://fywonton.com.tw/article_d.php?lang=tw&tb=2&id=94"}]},"4":{"title":"Boulder Space Zuoying — Indoor Bouldering","hours":"Global Mall 3F (享樂天地) Fri 11:00–22:00","cost":"Single entry adult NT$350 + shoe rental NT$80 = NT$430 (Global Mall Online voucher, pickup at the Boulder Space counter)","getThere":"Global Mall Xinzuoying, 高雄市左營區站前北路1號 3F — same building as TRA Xinzuoying and connected to THSR Zuoying.","watch":"Gym-specific hours and walk-in rules are not on an official page; the mall's 3F hours (Fri 11:00–22:00) are the outer limit.","highlights":["Bouldering-focused gym with varied wall angles and training equipment; suits beginners and experienced climbers.","Shoe rental is bundled in the NT$430 online product."],"tips":["Buy the NT$430 product on Global Mall Online (credit card, LINE Pay, JKOPAY, 悠遊付, iPASS MONEY) to skip pricing questions at the desk.","Mall 2F has food outlets for a post-climb protein snack."],"sources":[{"label":"Global Mall Online: Boulder Space single entry + shoes","url":"https://gmonline.twglobalmall.com/product/2C10501510000018"},{"label":"Global Mall Xinzuoying hours","url":"https://www.twglobalmall.com/branch/7/8"}]},"5":{"title":"Collect Luggage → Airline Inn Check-In","hours":"Check-in from 3:00 PM; check-out 11:00 AM","getThere":"From Zuoying take the KMRT Red Line to Kaohsiung Main Station (R11), then walk 3–5 min to 高雄市三民區建國三路33號. TRA Kaohsiung Station is also a 3–5 min walk.","watch":"Hotel is entirely non-smoking; only partner car parks (paid, first-come).","highlights":["134-room hotel in front of Kaohsiung Main Station; tel +886-7-285-3888.","Staff languages: Chinese, English, Japanese."],"tips":["Arriving before 3 PM: ask the front desk to hold bags, then head to Pier-2 and check in later.","Since 1 Jan 2025 no single-use toiletries are placed in rooms — ask the front desk if needed."],"sources":[{"label":"Airline Inn Kaohsiung Station — About","url":"https://www.airlineinn.com/KS/about_us.php"},{"label":"Airline Inn — Location & transport","url":"https://www.airlineinn.com/KS/location.php"},{"label":"Airline Inn — amenities notice","url":"https://www.airlineinn.com/KS/news.php?number=14"}]},"6":{"title":"Pier-2 / Warehouse & Harbour Corridor","hours":"Fri 10:00–20:00 (Mon–Thu 10:00–18:00). Ticketed exhibits: last ticket sale 19:00 on Fri. Pier-2 Tower Fri 10:00–19:30","cost":"Outdoor areas free. 駁二當代館 combo (C5 + 舊事倉庫) NT$120; single exhibit NT$80. Pier-2 Tower NT$10 coin entry","getThere":"大勇路1號, 鹽埕. Nearest stops: KMRT Yanchengpu (O2), Light Rail 駁二大義 / 駁二蓬萊. Hamasen MRT/LRT for the west end.","watch":"2026駁二動漫祭 runs Sat–Sun Dec 5–6 in P2/P3/自行車倉庫 and B3/B4/B9 — expect setup or closures there on Fri Dec 4.","highlights":["Walk the Dayong (P2/P3/C-warehouses) → Dayi (C6–C11) → Penglai (B-warehouses) strip along the light-rail line.","Pier-2 Tower: NT$10 coin entry for a harbour view.","Continue west to 舊打狗驛故事館 and 哈瑪星鐵道園區 if time allows."],"tips":["Tickets are sold at the C5 問吧 desk (Dayong) and C7 desk (Dayi).","Exhibitions: no food/drink, no flash, no running."],"sources":[{"label":"Pier-2 official (hours, map, events)","url":"https://pier2.org/"},{"label":"Pier-2 ticket info","url":"https://pier2.org/ticket/"}]},"7":{"title":"Yancheng Early Dinner","hours":"鴨肉珍: Fri 10:00–20:20 (closed Tue)","getThere":"KMRT Yanchengpu (O2) is the hub; the Bib Gourmand shops are a short walk in the 鹽埕 grid.","watch":"鄭家切仔麵 closes at 15:00 daily — not a dinner option.","highlights":["鴨肉珍 — Michelin Bib Gourmand; duck rice and duck meat, a lean protein pick that runs past 8 PM.","Other Bib picks in Yancheng named by Kaohsiung Tourism: 北港蔡三代筒仔米糕, 鄭家切仔麵."],"tips":["Go to 鴨肉珍 first — it closes 20:20.","Pair duck with a meat-heavy side to hit the protein target before E7PLAY."],"sources":[{"label":"Kaohsiung Tourism: 鴨肉珍","url":"https://khh.travel/zh-tw/shop/gourmet/796/"},{"label":"Kaohsiung Tourism: 鹽埕 eating guide (Bib picks)","url":"https://khh.travel/zh-tw/event/news/5094/"},{"label":"Kaohsiung Tourism: 鄭家切仔麵 hours","url":"https://khh.travel/zh-tw/shop/gourmet/790/"}]},"11":{"title":"E7PLAY Sanduo — Bowling, Billiards, Darts, Arcade","hours":"08:30–02:30 daily, all year","cost":"Fri entry after 18:00 = holiday rate (non-member): 3 h NT$350, 5 h NT$430, plus 10% cleaning fee (3 h = NT$385). Overtime NT$60 per 30 min","getThere":"高雄市苓雅區三多一路335號2F (above 小北百貨, opposite 三信家商), tel (07)727-0853. KMRT 五塊厝 Exit 4 is the operator's suggested approach.","watch":"Card payments listed are Taiwan-issued Visa/Mastercard/JCB, LINE Pay, TWQR — bring cash. Under-18s, or adults without ID, must leave by midnight.","highlights":["One ticket covers bowling, billiards, darts, KTV booths, arcade machines and massage chairs.","Glow bowling (夜光保齡球) session at 23:00 — right at the end of a 9 PM entry."],"tips":["A 9 PM entry on a 3 h ticket ends at midnight — matches the plan.","First-time E7 app sign-up gives a buy-one-get-one ticket coupon; member discounts need the in-app card."],"sources":[{"label":"E7PLAY Sanduo price table","url":"https://e7play.com.tw/index.php/all-shop/kaohsiung-sanduo/e7play03price"},{"label":"E7PLAY Sanduo store & transport","url":"https://www.e7play.com.tw/index.php/all-shop/kaohsiung-sanduo/e7play03shop"}]}}},"day-08":{"checked":"2026-11-11","items":{"0":{"title":"TRA: Kaohsiung → Bao'an Station","hours":"Sat Dec 5 direct locals Kaohsiung→Bao'an: 3146 07:50→08:52 · 3152 08:24→09:20 · 3158 08:53→09:43 · 3162 09:26→10:22","cost":"NT$85 adult (local train, one way)","getThere":"TRA Kaohsiung Station is a 3–5 min walk from Airline Inn. All four trains are direct 區間 (local) services; no change needed.","watch":"Bao'an is a small station — confirm the train actually stops there (all four listed above do).","highlights":["3152 (08:24→09:20) lands just before Ten Drum's 09:30 Saturday opening.","3146 (07:50→08:52) gives a buffer if you want breakfast near Bao'an."],"tips":["Local (區間) trains are non-reserved — no seat booking needed.","Child/senior fare on these locals is NT$43."],"sources":[{"label":"TRA timetable search (Kaohsiung→Bao'an, 2026/12/05)","url":"https://tip.trc.com.tw/tra-tip-web/tip/tip001/tip112/gobytime"},{"label":"Airline Inn — location","url":"https://www.airlineinn.com/KS/location.php"}]},"1":{"title":"Bao'an Station → Ten Drum (walk or short taxi)","getThere":"Bao'an Station: 臺南市仁德區文賢路一段529巷10號. Ten Drum: 臺南市仁德區文華路二段326號 (tel 06-2662225).","highlights":["Bao'an Station (built 1899, Alishan cypress) is Taiwan's best-preserved Japanese-era wooden station — worth 5 min of photos.","The station is open all year and free to look around."],"tips":["Ten Drum opens 09:30 on Saturdays, so arriving on the 09:20 train is ideal.","Weekday hours are different (10:00–17:20) — the Saturday times apply on Dec 5."],"sources":[{"label":"Tainan Travel: Bao'an Station","url":"https://www.twtainan.net/zh-tw/attractions/detail/571/"},{"label":"Tainan Travel: Ten Drum","url":"https://www.twtainan.net/zh-tw/attractions/detail/816/"}]},"2":{"title":"Ten Drum Cultural Village","hours":"Sat 09:30–17:50 (Mon–Fri 10:00–17:20). Drum shows 11:00 and 15:00. Some halls/rides pause 11:45–13:10 for maintenance","cost":"Adult NT$509 at gate; NT$458 online via Ten Drum's LINE (valid 2026/1/1–12/31, exchange at ticket booth on the day and book a show slot). Extra show NT$300","getThere":"臺南市仁德區文華路二段326號 — near TRA Bao'an Station.","watch":"Single same-day entry — leaving means a new ticket. Sign the extreme-activity consent form. Pole Rowing had November closure dates; check the facility notice for December.","highlights":["Ticket includes unlimited use of the 'extreme' facilities: Sky Swing (min 120 cm, 25–180 kg), Free Fall and Outdoor Zipline (min 120 cm, 30–110 kg).","Also: Chimney Slide, Transparent Climbing Wall, Outdoor Archery, Pole Rowing, Laser Tag (min 140 cm).","One drum show per ticket (11:00 or 15:00); seats chosen when you exchange the ticket."],"tips":["Zipline, Sky Swing, Free Fall and Laser Tag open from 13:10 — do archery, chimney slide and climbing wall in the morning.","Wear closed-toe shoes and trousers: high rides need closed-toe shoes and some walkways are see-through.","Lunch during the 11:45–13:10 pause: 十鼓餐廳, 蜜橋咖啡, 修護書屋, 鼓找冰屋 stay open."],"sources":[{"label":"Ten Drum opening hours","url":"https://www.tendrum.com.tw/TpLandTime/zt"},{"label":"Ten Drum 2026 tickets","url":"https://www.tendrum.com.tw/TpElecsTicket/zt"},{"label":"Ten Drum 2026 hours/show-time card","url":"https://www.tendrum.com.tw/userfiles/images/2026%E7%A5%A8%E5%83%B9%E8%A1%A8_140x80(1).jpg"},{"label":"Ten Drum facility rules & times","url":"https://www.tendrum.com.tw/TpNewsInfo/zt/463"}]},"3":{"title":"Taxi into Central Tainan","cost":"TRA alternative: NT$22 Bao'an→Tainan (local)","getThere":"Cheaper than a taxi: TRA Bao'an→Tainan locals on Dec 5 at 15:37→15:43, 15:48→15:54, 16:08→16:14, 16:13→16:20, 16:33→16:39 (6–7 min). From Tainan Station take a short taxi to the food stop.","highlights":["Trains run every 10–20 min in the late afternoon.","The ride is only 6–7 min to Tainan Station."],"tips":["Ten Drum closes 17:50 on Saturdays; later Bao'an→Tainan locals also run (16:45, 16:54).","Wusheng Night Market opens at 17:00, so there is no need to rush."],"sources":[{"label":"TRA timetable search (Bao'an→Tainan, 2026/12/05)","url":"https://tip.trc.com.tw/tra-tip-web/tip/tip001/tip112/gobytime"}]},"5":{"title":"Wusheng Night Market — Food & Games","hours":"Wed, Fri, Sat 17:00–00:00 (closed Sun–Tue, Thu) — Saturday Dec 5 is an operating night","getThere":"臺南市中西區武聖路69巷42號 — the square at 武聖路69巷 × 光賢街.","watch":"If Wusheng is too crowded, Garden Night Market (北區) also runs on Saturdays (Thu–Sun).","highlights":["~330 stalls; opened 1984; rated a 4-star market (MOEA 2024).","Strong on old-school games: ring toss (套圈圈), pinball (打彈珠).","3-star stalls: 陳家阿嬤拔絲地瓜 (candied sweet-potato fries), 古玥茶 (soy-milk black tea, herbal black tea)."],"tips":["Arrive near 17:00 opening to play games before the crowd.","Eat the protein-heavy stalls first, then the rated sweet-potato and tea stalls for dessert."],"sources":[{"label":"Tainan Travel: Wusheng Night Market","url":"https://www.twtainan.net/zh-tw/attractions/detail/6108/"},{"label":"Tainan Market Office: 武聖夜市","url":"https://marketoffice.tainan.gov.tw/News_Content.aspx?n=44651&s=8747428"},{"label":"Tainan Travel: night-market schedule","url":"https://www.twtainan.net/zh-tw/statics/night-market/"}]},"6":{"title":"Taxi to Tainan Station → TRA to Kaohsiung","hours":"Sat Dec 5 Tainan→Kaohsiung: 自強141 21:54→22:31 · 區間3281 22:13→23:17 · 自強145 22:29→23:05 · 區間3271 22:36→23:34 · 區間3287 22:54→23:52 · 自強149 23:22→23:57 · last 自強281 23:46→00:21","cost":"Tze-Chiang (自強) NT$158; local (區間) NT$102 (adult, one way)","getThere":"Tainan Station → Kaohsiung Station, then 3–5 min walk to Airline Inn.","watch":"Last train is 自強281 at 23:46 (arrives 00:21). Child/senior fares: 自強 NT$79, 區間 NT$51.","highlights":["自強145 (22:29→23:05) fits the 'back ~11:15 PM' target.","Tze-Chiang trains take 30–37 min; locals take ~1 h."],"tips":["Book a Tze-Chiang seat on the TRA app/site in advance for a Saturday night.","Missed 22:29? 自強149 at 23:22 arrives 23:57."],"sources":[{"label":"TRA timetable search (Tainan→Kaohsiung, 2026/12/05)","url":"https://tip.trc.com.tw/tra-tip-web/tip/tip001/tip112/gobytime"},{"label":"Airline Inn — location","url":"https://www.airlineinn.com/KS/location.php"}]}}},"day-09":{"checked":"2026-11-11","items":{"0":{"title":"Private Charter Pickup → Maolin","hours":"Maolin Visitor Center (茂林巷7-7號): 09:00–17:00, tel 07-680-1111.","getThere":"Private charter from the hotel to Maolin District. The Maolin NSA recommends self-drive or a charter for this mountain area (public buses and Taiwan Tourist Shuttles are limited/reservation-only).","tips":["Ask the driver to fuel up before leaving the plains — the Maolin NSA explicitly advises filling the tank before entering the mountain area.","Butterflies are most active on calm, sunny mornings from first light to about 11 AM, so the 7:15 AM pickup is justified; don't let breakfast delay departure."],"sources":[{"label":"Maolin NSA – How to get to Maolin","url":"https://www.maolin-nsa.gov.tw/zh-tw/go-to-maolin/"},{"label":"Maolin NSA – Butterfly viewing guide","url":"https://www.maolin-nsa.gov.tw/zh-tw/butterfly/"}]},"1":{"title":"Maolin Purple Butterfly Valley","hours":"Ecological park open 24 h; best viewing from first light to about 11 AM on calm, sunny mornings. Season October – end of February.","cost":"Free entry.","getThere":"Park entrance opposite 高雄市茂林區茂林里1鄰16號; park in the Purple Butterfly Ecological Park car park (official advice for the butterfly season).","watch":"Rules: no catching butterflies, no shaking trees or throwing objects, don't enter overwintering valleys without permission (some are private land), slow down when driving through the valley. Rainy/overcast days mean little activity.","highlights":["Walk the 姿沙里沙里步道 from the park: 2.1 km open section (~50 min), a key overwintering cluster spot; viewing deck over Maolin village, then 瑪雅亭 lookout over the Zhuokou/Laonong river confluence.","Four species overwinter here: 小紫斑蝶, 圓翅紫斑蝶, 斯氏紫斑蝶, 端紫斑蝶 (mnemonic: one dot / two dots / three dots / scattered dots).","Before sun hits the valley, look for 'butterfly trees' — wings closed, hanging in grape-like bunches — then watch them open to sunbathe.","Best case per the NSA: a sunny day right after rain, when swarms glide down the valley to drink (\"butterfly carpet\")."],"tips":["Check the official daily forecast (蝶況預報) the evening before: it rates butterfly numbers 1–5 stars and names the best trail and window for that day.","Season events run Oct 31 2026 – Mar 31 2027, with interpretation at the ecological park entrance.","Bring sun protection and insect repellent; dress for outdoor walking."],"sources":[{"label":"Maolin NSA – Butterfly viewing guide","url":"https://www.maolin-nsa.gov.tw/zh-tw/butterfly/"},{"label":"Maolin NSA – Purple Butterfly Ecological Park","url":"https://www.maolin-nsa.gov.tw/zh-tw/attraction/58/"},{"label":"Maolin NSA – 姿沙里沙里步道","url":"https://www.maolin-nsa.gov.tw/zh-tw/attraction/60/"},{"label":"Maolin butterfly forecast (蝶況預報)","url":"https://theme.maolin-nsa.gov.tw/maolin-butterfly/pre.aspx"}]},"2":{"title":"Butterfly Festival Market (Dec 5–6)","hours":"Sat Dec 5 – Sun Dec 6 2026, 10:00–16:00 (2nd of 5 sessions; this one at the Purple Butterfly Ecological Park).","cost":"Free; DIY is free with on-site sign-up.","watch":"Later sessions (Jan 16–17 Dream Mall, Feb/Mar Aozihdi Forest Park) are in the city, not Maolin — Dec 5–6 is the last Maolin date this season.","highlights":["Programme: 09:55 host intro · 10:00–11:00 DIY part 1 · 11:00–12:00 singers part 1 · 12:00–14:00 music/break · 14:00–15:00 DIY part 2 · 15:00–16:00 singers part 2.","Rukai-community 護蝶市集 with local culture, food and crafts; Dec 5–6 DIY is a 陶壺皮雕 (pottery-pot leather-carving) keychain."],"tips":["Arriving ~10:00 puts you in the DIY slot; the first singers start at 11:00 — after your planned 10:25 departure.","DIY (if anyone wants it): 30 places per session, register at the market service desk 30 min before the session."],"sources":[{"label":"Maolin butterfly season – 護蝶市集 (official)","url":"https://theme.maolin-nsa.gov.tw/maolin-butterfly/zh-tw/market.html"},{"label":"Tourism Administration event listing","url":"https://media.taiwan.net.tw/zh-tw/portal/travel/details/event_a15010900h_005680"}]},"3":{"title":"Drive to Qishan","getThere":"Charter car to Qishan Old Street; the old street runs along 中山路, 復興街 and 華中街 and starts at Qishan Station (中山路1號).","tips":["Drop at Qishan Station/old street rather than at the temple — streets around 旗山天后宮 are likely to be crowded on procession day."],"sources":[{"label":"Kaohsiung Travel – Qishan Old Street","url":"https://khh.travel/zh-tw/attractions/detail/157/"}]},"5":{"title":"2026 Qilu Tongfu Mazu Procession — Qishan","hours":"Sun Dec 6 2026; Kaohsiung Travel lists timing 'per organiser's latest announcement'.","cost":"Free.","watch":"Expect heavy crowds and road control around the temple; do not touch the palanquin or sacred objects.","highlights":["Official name 2026旗鹿同福 聖母巡安; organisers 鹿港天后宮 and 旗山天后宮. Lukang Mazu travels from Changhua to Qishan Tianhou Temple for a joint double-Mazu procession.","Crawling under the palanquin (躦轎腳) for blessings is opened at specific locations; those locations/times are announced by the temple.","Qishan Tianhou Temple itself: completed 1824, a Kaohsiung municipal heritage site known for its imperially-honoured Tiger General (金虎將軍)."],"tips":["The temple says it posted the joint route on its Facebook page on Nov 3, warning times may run early or late with crowds and rituals — get the route image before Dec 6 (FB requires login).","Temple service line: 07-661-2037."],"sources":[{"label":"Kaohsiung Travel – event listing","url":"https://khh.travel/zh-tw/event/calendardetail/8049/"},{"label":"News586 via yam – event announcement","url":"https://n.yam.com/Article/20260919386374"},{"label":"Twpowernews via yam – temple phone","url":"https://n.yam.com/Article/20260926759722"},{"label":"Search snippet of 旗山天后宮 FB route post (Nov 3)","url":"https://www.bing.com/search?q=%E6%97%97%E9%B9%BF%E5%90%8C%E7%A6%8F+%E9%81%B6%E5%A2%83%E8%B7%AF%E7%B7%9A+%E5%85%AC%E5%B8%83+%E8%B5%B7%E9%A7%95"}]},"7":{"title":"Driver Back to Kaohsiung (or Stay in Qishan)","getThere":"Have the driver drop you by Kaohsiung Arena; if you come by MRT instead, Red Line to 巨蛋 (R14) Exit 1.","tips":["Ruifeng opens at 17:00 — arriving 17:15–18:00 is right as stalls start up."],"sources":[{"label":"Kaohsiung Travel – Night markets","url":"https://khh.travel/zh-tw/board-and-lodging/night-market/"},{"label":"KRTC – Kaohsiung Arena station","url":"https://www.krtc.com.tw/Guide/station_info?id=bd5435a1ddc7441eb7d2e957ea074eb4"}]},"8":{"title":"Ruifeng Night Market — Backup Dinner & Games","hours":"17:00–00:00; closed Mondays and Wednesdays — open Sunday Dec 6.","getThere":"Red Line 巨蛋 (R14), Exit 1.","highlights":["Near the Arena shopping district; over a thousand stalls laid out in an L-shaped, managed grid.","Mix of decades-old classic snacks, international stalls and newer creative dishes and drinks; Kaohsiung markets keep old-style games such as ring toss and balloon shooting."],"sources":[{"label":"Kaohsiung Travel – Night markets","url":"https://khh.travel/zh-tw/board-and-lodging/night-market/"}]},"9":{"title":"Kaohsiung Music Center → Love River","hours":"KMC outdoor areas open; indoor venues only for events","getThere":"Light Rail: C10 光榮碼頭 for the Coral Reef / Whale Embankment, C11 真愛碼頭 for the Wave Tower (音浪塔), C12 駁二大義 for LIVE WAREHOUSE. KMC address 真愛路1號.","watch":"Gondola fares/schedules aren't published on the tourism page — ask at the dock.","highlights":["Walk the KMC waterfront (Wave Tower, Coral Reef, Whale Embankment), then follow the Love River north-east.","Love River night lights run from 愛河之心 and 光之塔 down to 真愛碼頭.","Gondola rides board at 河東路 × 民生路; round trip about 25 min, passing under 五福橋 (zodiac lights)."],"tips":["KMC has rentable lockers (40 small 32.5×40.4 cm, 4 medium, 2 large).","Riverside paths have cafés and, on weekends, food-truck markets."],"sources":[{"label":"KMC directions & opening","url":"https://kpmc.com.tw/transportation/"},{"label":"Kaohsiung Tourism: Love River","url":"https://khh.travel/zh-tw/attractions/detail/232/"}]},"10":{"title":"Liuhe / Formosa Boulevard Late Pass","hours":"Liuhe Night Market daily 17:00–02:00.","getThere":"Red Line R14 巨蛋 → R10 美麗島 (4 stops). Exits 1 and 11 are signed for 六合觀光夜市.","highlights":["Dome of Light (光之穹頂): Narcissus Quagliata's glass artwork, described as the world's largest glass mosaic work, inside the Red/Orange interchange station.","Liuhe dates from the 1950s; Liuhe 2nd Rd is pedestrianised at night. Signature items lean seafood (seafood congee, salt-steamed shrimp, mullet gizzard)."],"tips":["Treat Liuhe as dessert or one snack, as planned; a seafood signature works as that snack.","Station has 11 exits — follow signs for Exit 1 or 11 to avoid surfacing on the wrong side of Zhongshan Rd."],"sources":[{"label":"Kaohsiung Travel – Night markets","url":"https://khh.travel/zh-tw/board-and-lodging/night-market/"},{"label":"KRTC – Formosa Boulevard station","url":"https://www.krtc.com.tw/Guide/station_info?id=6d709285233f48249ff3668e5851e6a0"},{"label":"Kaohsiung Travel – Dome of Light","url":"https://khh.travel/zh-tw/attractions/detail/159/"}]},"11":{"title":"Back to the Hotel","getThere":"Red Line from 美麗島 (R10) one stop north (toward 岡山車站) to 高雄車站 (R11). Last train toward 岡山車站 from 美麗島: 24:21 (all days).","sources":[{"label":"KRTC – Formosa Boulevard first/last trains","url":"https://www.krtc.com.tw/Guide/station_traintime?id=6d709285233f48249ff3668e5851e6a0"},{"label":"KRTC – station list","url":"https://www.krtc.com.tw/Guide/station_guide?id=R10"}]}}},"day-10":{"checked":"2026-11-11","items":{"1":{"title":"Taxi to the Shoushan Trailhead","getThere":"Taxi to the 龍泉寺 trailhead (route 1 of the seven Chaishan trail routes starts at 龍泉寺登山口). Kaohsiung Travel lists parking at the Chaishan trails.","tips":["Eat before leaving and pack food in a closed bag — macaques frequent the trails from the trailhead onward."],"sources":[{"label":"Kaohsiung Travel – Chaishan trails (Shoushan NNP)","url":"https://khh.travel/zh-tw/attractions/detail/1231/"}]},"2":{"title":"Shoushan / Chaishan Hike","cost":"Free.","watch":"Limestone and roots get slippery in rain; skip 盤榕道 if wet. Keep food sealed and don't feed or approach macaques.","highlights":["Seven marked routes on raised-coral limestone; mostly boardwalk, but 盤榕道 (banyan-root route) needs hands and feet among boulders — the fit-hiker option.","Look for 泰國谷, 一線天 and 一簾幽夢 rock/banyan scenery; the popular end-point 雅座亭 looks out over the Taiwan Strait.","Former military land opened from 1989, so native forest is well preserved; wild Formosan macaques and squirrels are common."],"tips":["Trail signposts give walking times between junctions — use them to time the descent for the late-morning ferry.","Kaohsiung Travel publishes a map of mobile-signal points on the main Shoushan trails; download offline maps."],"sources":[{"label":"Kaohsiung Travel – Chaishan trails (Shoushan NNP)","url":"https://khh.travel/zh-tw/attractions/detail/1231/"},{"label":"Kaohsiung Travel – Shoushan National Nature Park","url":"https://khh.travel/zh-tw/attractions/detail/102/"}]},"4":{"title":"Descend to Gushan → Ferry to Cijin","hours":"Mon Dec 7 = weekday timetable: 09:50–16:10 a boat roughly every 12–15 min (08:30–09:50 and 16:10–20:00 every 8–12 min). Crossing ~5 min.","cost":"Adult pedestrian NT$30 cash (discounted from NT$40) or NT$30 by iPASS/EasyCard/icash2.0.","getThere":"Gushan Ferry Station, 高雄市鼓山區濱海二路1號 → Cijin Ferry Station, 旗津區海岸路10號.","watch":"Gushan station building is being rebuilt (its phone line is diverted to 07-571-2542); boats run, but confirm the temporary boarding point on arrival.","highlights":["Cijin Ferry Station reopened in July 2026 as the new '光之渡口' (Ferry of Light) building."],"tips":["Have coins ready — cash fares are paid by dropping coins at boarding (請自備零錢投幣登船); tapping an EasyCard/iPASS is the same NT$30.","Timetable is indicative only: tides, weather and ship traffic in the harbour can shift sailings."],"sources":[{"label":"Kaohsiung City Shipping – Gushan–Cijin route (fare & timetable images)","url":"https://kcs.kcg.gov.tw/en/Content_List.aspx?n=832C80D391F0764A"},{"label":"Kaohsiung City Shipping – home (renovation notice, news)","url":"https://kcs.kcg.gov.tw/Default.aspx"},{"label":"Kaohsiung Travel – Waterborne transport","url":"https://khh.travel/zh-tw/traffic/waterborne-traffic/"}]},"5":{"title":"Cijin Headland — Lighthouse, Fort, Coastal Paths","hours":"Kaohsiung Lighthouse: 10:00–21:00 daily, no closing day (Monday closure was dropped). Cihou Fort: open 24 h.","getThere":"Lighthouse: 高雄市旗津區旗下巷34號, on top of 旗後山 (tel 07-571-5021). The fort sits on the south side of the same hill, facing the lighthouse.","highlights":["Lighthouse built 1883 by British engineer John Reginald Harding, rebuilt 1918; Taiwan's only white octagonal brick lighthouse (15.2 m tower, light 58.2 m above sea).","Its wind vane is the only one in Taiwan marked with Chinese characters 東西南北; small exhibition of old lighthouse equipment, sundial on the lawn, café on site.","Cihou Fort: largest and best-preserved of the harbour's three forts; red brick with 囍 and bat motifs and the '威震天南' gate inscription.","From the fort: Port No. 1 breakwaters, Cijin Beach and the city skyline — good for watching big ships enter."],"sources":[{"label":"Maritime and Port Bureau – Kaohsiung Lighthouse","url":"https://www.motcmpb.gov.tw/Lighthouse/Detail/2f3c9806-8e45-404c-9938-cbc98d879d5f?SiteId=1&NodeId=50091"},{"label":"Kaohsiung Travel – Kaohsiung Lighthouse","url":"https://khh.travel/zh-tw/attractions/detail/119/"},{"label":"Kaohsiung Travel – Cihou Fort","url":"https://khh.travel/zh-tw/attractions/detail/259/"}]},"7":{"title":"Optional Hotel Shower Stop","cost":"Ferry NT$30 per adult.","getThere":"Ferry back to Gushan (weekday boats every ~12–15 min until 16:10, then every 8–12 min), then KRTC Orange Line from O1 哈瑪星 to O5/R10 美麗島, change to the Red Line one stop north to R11 高雄車站.","sources":[{"label":"Kaohsiung City Shipping – Gushan–Cijin route","url":"https://kcs.kcg.gov.tw/en/Content_List.aspx?n=832C80D391F0764A"},{"label":"KRTC – station list","url":"https://www.krtc.com.tw/Guide/station_guide?id=R10"}]},"8":{"title":"Travel North to Zuoying","getThere":"From R11 高雄車站 the Red Line runs north via R13 凹子底, R14 巨蛋 and R15 生態園區 to R16 左營; a taxi straight to 文慈路76號 avoids an unverified last-mile walk.","sources":[{"label":"KRTC – station list","url":"https://www.krtc.com.tw/Guide/station_guide?id=R10"}]},"9":{"title":"Shrimp Fishing — 佰吉星釣蝦競技場","getThere":"高雄市左營區文慈路76號 (same address previously listed for 佰吉興 shrimp hall).","watch":"All details here come from social posts, not an official listing — verify opening hours, pricing and whether rods can be shared before committing the evening.","highlights":["An Oct 10 2026 food-blogger reel describes it as newly (re)opened as a shrimp-fishing + stir-fry (熱炒) venue with big Thai prawns in many flavours, golden-sand squid, crispy ginger chicken and squid-conch-garlic soup."],"tips":["Hours and rod prices are still not published by the venue; phone 07-350-3909 (number from the existing plan) the day before.","A July 2026 post on the venue's FB (seen via search snippet) announced an internal renovation and '全新升級 即將登場'; the Oct reel suggests it has reopened."],"sources":[{"label":"food_fat_plan Instagram reel (Oct 10 2026)","url":"https://www.instagram.com/reel/DeUFlYQM5Tg/"},{"label":"Search results for the venue (FB/IG snippets)","url":"https://www.bing.com/search?q=%E4%BD%B0%E5%90%89%E6%98%9F%E9%87%A3%E8%9D%A6+%E6%96%87%E6%85%88%E8%B7%AF76%E8%99%9F"}]},"10":{"title":"Grill the Catch → Proper Dinner","watch":"Cooking-fee and menu prices not published; ask when ordering.","highlights":["Per the Oct 2026 reel, shrimp you catch can be cooked by the kitchen on request (代客料理), and there's a full stir-fry/grill/fried menu — so the 'late meal' can happen in the same venue."],"tips":["Order a chicken or pork stir-fry alongside the shrimp to round out the protein."],"sources":[{"label":"food_fat_plan Instagram reel (Oct 10 2026)","url":"https://www.instagram.com/reel/DeUFlYQM5Tg/"},{"label":"Search results for the venue (reel snippet incl. 代客料理)","url":"https://www.bing.com/search?q=%E4%BD%B0%E5%90%89%E6%98%9F%E9%87%A3%E8%9D%A6+%E6%96%87%E6%85%88%E8%B7%AF76%E8%99%9F"}]},"12":{"title":"Back to the Hotel","getThere":"Taxi, or Red Line south (toward 小港) from the Zuoying-area stations (R16 左營 / R14 巨蛋 / R13 凹子底) to R11 高雄車站.","sources":[{"label":"KRTC – station list","url":"https://www.krtc.com.tw/Guide/station_guide?id=R10"}]}}},"day-11":{"checked":"2026-11-11","items":{"0":{"title":"Breakfast","hours":"Hotel breakfast restaurant (B1) posted as 7:00–9:30 AM on weekdays (7:00–10:00 weekends); Tue Dec 8 is a weekday.","watch":"Breakfast hours come from a 2024 hotel post; the hotel says special dates may differ and are announced at check-in. Confirm the time at the desk the night before.","highlights":["Buffet per the hotel's own post: congee with side dishes, cold noodles, salads, fruit, bread and toast, hot vegetables, egg dishes, soup, coffee and tea.","Eggs from the hot counter are the easiest protein before a long transit day."],"tips":["Hotel checkout is 11:00 AM, so the 8:30 AM departure is your own schedule, not a hotel constraint.","Breakfast opens at 7:00, so a 7:00–7:45 sitting buys margin if you choose the 9:00 AM THSR (see the THSR item)."],"sources":[{"label":"Airline Inn Kaohsiung Station (official site: address, check-in/out)","url":"https://www.airlineinn.com/KS/about_us.php"},{"label":"Search result showing the hotel's Facebook post (breakfast B1, weekday 7:00–9:30)","url":"https://www.bing.com/search?q=%E9%A0%AD%E7%AD%89%E8%89%99%E9%A3%AF%E5%BA%97+%E9%AB%98%E9%9B%84%E7%AB%99%E5%89%8D%E9%A4%A8+%E6%97%A9%E9%A4%90%E6%99%82%E9%96%93"}]},"1":{"title":"Checkout → MRT to THSR Zuoying","hours":"Red Line from R11 Kaohsiung Main Station toward Gangshan: first train 06:00 on workdays.","getThere":"Walk ~500 m from the hotel (33 Jianguo 3rd Rd) to MRT R11 Kaohsiung Main Station (Exits 1–4; Exits 1–3 have lifts). Take the Red Line in the 'Up' direction (toward Gangshan) to R16 Zuoying, then Exit 1, signed 'THSR Zuoying Station'.","watch":"The KRTC fare and journey time for R11→R16 weren't verifiable on the operator's site, so plan your own buffer for the THSR departure you choose.","highlights":["R16 Zuoying Exit 1 connects to THSR Zuoying; Exit 2 goes to TRA New Zuoying.","Both R11 and R16 have island platforms, so you don't need to switch platforms with luggage."],"tips":["Use the lift at R11 Exits 1–3 with suitcases; Exit 4 has only an up escalator.","Allow extra time at Zuoying to get from the MRT to the THSR gates and pick up tickets if you didn't buy them online."],"sources":[{"label":"KRTC R11 Kaohsiung Main Station: exits and lifts","url":"https://www.krtc.com.tw/eng/Guide/station_info?id=bbca0fceac624e1c955f499d242ec1aa"},{"label":"KRTC R11 first and last trains","url":"https://www.krtc.com.tw/eng/Guide/station_traintime?id=bbca0fceac624e1c955f499d242ec1aa"},{"label":"KRTC R16 Zuoying: Exit 1 to THSR","url":"https://www.krtc.com.tw/eng/Guide/station_info?id=e9d98c3129844b4c8a7d88814f89135a"},{"label":"Airline Inn official: ~500 m from station","url":"https://www.airlineinn.com/KS/about_us.php"}]},"2":{"title":"THSR: Zuoying → Taoyuan","hours":"Tue Dec 8 departures from Zuoying: 0616 08:35→10:09; 0618 09:00→10:36; 0814 09:25→11:18 (stopping train); 0622 09:35→11:09; 0624 10:00→11:36.","cost":"Adult one-way, Zuoying→Taoyuan: Standard reserved NT$1,330; Business NT$2,200; Non-reserved NT$1,290. Child/concession: NT$665 / NT$1,100 / NT$645.","getThere":"THSR Zuoying (south terminus) to Taoyuan: about 1 h 34–36 min on the faster trains (0616, 0618, 0622), or 1 h 53 min on 0814.","watch":"There is no 9:15 AM departure. If you take the 09:35, you reach T1 around 11:36, which still leaves margin before the 12:20 counter close. Your booked ticket is final.","highlights":["Best fit for the plan is 0618 at 09:00 (arrives 10:36). The 0622 at 09:35 (arrives 11:09) also works.","Non-reserved seats are in cars 10–12 on trains 0616, 0618 and 0622."],"tips":["Book reserved seats now: the timetable for Dec 8 already shows on THSR's search page.","The 0814 shows Early Bird and student discounts but takes 19 minutes longer. Choose a faster train unless the saving matters."],"sources":[{"label":"THSR Timetable and Fare Search (queried for 2026/12/08)","url":"https://en.thsrc.com.tw/ArticleContent/a3b630bb-1066-4352-a1ef-58c7b4e8ef7c"}]},"3":{"title":"Taoyuan Airport MRT: THSR → TPE Terminal 1","hours":"Midday A18→A12 commuter trains leave at :02, :17, :32 and :47 past each hour (for example 10:47→11:06 and 11:17→11:36).","cost":"Single-journey ticket A18→A12: NT$35 (full fare).","getThere":"Walk from the THSR Taoyuan concourse to Airport MRT A18 Taoyuan HSR Station. Take a commuter train (all stops) to A12 Airport Terminal 1, 19 minutes.","watch":"The operator says its timetable is for reference only. Leave buffer for airport formalities: the airport advises reaching airline counters 2–3 hours before departure.","highlights":["From 10:30 to about 17:00 only commuter trains serve A18 toward the airport. Express trains stop at A18 only at set peak times.","If you take THSR 0618 (arrives 10:36), catch the 10:47 and reach A12 at 11:06. With 0622 (arrives 11:09), catch the 11:17 and reach A12 at 11:36."],"tips":["Buy single-journey tokens at the machines or the information counter, or tap a stored-value card.","Express trains (purple line) skip A18, so board the commuter train shown on the A18 platform."],"sources":[{"label":"Taoyuan Metro route search A18→A12, 2026-12-08 (times and fare)","url":"https://www.tymetro.com.tw/tymetro-new/en/_pages/travel-guide/index.php"},{"label":"Taoyuan Metro timetable and train types","url":"https://www.tymetro.com.tw/tymetro-new/en/_pages/travel-guide/timetable.php"},{"label":"Taoyuan Metro single-journey tickets","url":"https://www.tymetro.com.tw/tymetro-new/en/_pages/travel-guide/ticketson01.php"}]},"4":{"title":"Check-in, Airside Lunch, Gate","hours":"Cathay Pacific TPE T1 counters open 180 min before departure (10:20 for CX495) and close at exactly 60 min before (12:20). Self-service kiosks and bag drop close 70 min before (12:10).","getThere":"Cathay Pacific check-in: Terminal 1, Counter 4. Self-service kiosks and bag drop at Counters 3/4.","watch":"Cathay says counters close at exactly 60 minutes before departure. Arriving after 12:10 rules out self-service bag drop.","highlights":["T1 3F Departure Area (airside) food options with posted hours: Burger King 06:00–23:00, Guiji 06:00–22:00, Hómee RICE 05:00–23:00, COMEME 06:00–22:00, Gontran Cherrier bakery 06:00–20:00, L.E.A.F CAFÉ 24 h.","Burger King or a rice set from Hómee RICE are the quickest protein-heavy choices before the flight."],"tips":["Check in online before you leave Kaohsiung, then use self-service bag drop. It closes 10 minutes earlier than the staffed counters.","The airport homepage shows live T1 security wait times; it read 10 min when checked."],"sources":[{"label":"Cathay Pacific – Taoyuan International Airport page","url":"https://www.cathaypacific.com/cx/en_TW/destinations/airports/taoyuan-international-airport.html"},{"label":"Taoyuan Airport dining – T1 Departure Area filter","url":"https://www.taoyuan-airport.com/services_facilities?lang=en&p=1&m=9CBEA40D-B7AB-EB11-AB4D-D45D6481BBEB&t=1&a=2"}]},"5":{"title":"Cathay Pacific CX495: Taipei → Hong Kong","hours":"Scheduled TPE 13:20 (Terminal 1) → HKG 15:25 (Terminal 1). Operates Tue–Sun.","watch":"The cabin type and meal in the app notes weren't independently verified here. Your booking and boarding pass take precedence.","highlights":["The timetable allows 2 h 05 min, but the flight usually takes about 1 h 20 min (806 km). Recent flights often landed 25–35 min early, around 14:45–15:05.","All of the last 9 flights tracked arrived on time (none 15+ min late)."],"tips":["An early arrival leaves more of the evening in Hong Kong. Plan on landing before 15:25 but don't rely on it.","Gate assignments change. On Nov 11 it left from TPE gate B6; check your boarding pass and the screens."],"sources":[{"label":"Airportia – CX495 schedule and history","url":"https://www.airportia.com/flights/cx495/taipei/hong-kong/"}]},"6":{"title":"Touchdown Hong Kong (HKG T1) → Immigration → Bags","getThere":"Arrival sequence: Immigration Hall → Baggage Reclaim → Customs & Excise → Arrivals Hall. The Airport Express ticket counters and trains are reached from the Arrivals Hall.","watch":"e-Channel pre-enrolment is only for eligible frequent visitors. First-time visitors should expect the staffed counters.","highlights":["Visitors need only a valid travel document at Immigration.","Eligible frequent visitors can pre-enrol for the e-Channel using the Immigration Department's 'Go Hong Kong' app."],"tips":["Have passports out before the Immigration Hall.","Declare any dutiable goods above the duty-free limits at Customs."],"sources":[{"label":"HKIA – Arrivals passenger guide","url":"https://www.hongkongairport.com/en/passenger-guide/arrivals/index.page"},{"label":"HKTB – Traveller Essentials (Go Hong Kong app, customs)","url":"https://www.discoverhongkong.com/eng/plan/getting-around/airport-express.html"}]},"7":{"title":"Airport Express to Kowloon → Sasa Inn","hours":"Airport Express runs about every 10 min, 05:54–00:48 daily (24 min to Hong Kong Station; Kowloon is the stop before).","cost":"Airport → Kowloon, adult: HK$115 single smart ticket or HK$105 Octopus (child HK$57.5 / HK$52.5).","getThere":"Airport Express to Kowloon Station, then a taxi to Sasa Inn: Flat C1, 8/F, Block C, Tsim Sha Tsui Mansion (華源大廈), 87 Nathan Road, Tsim Sha Tsui. Hotel nearest exit: TST MTR Exit C2.","watch":"The MTR website was down for maintenance during research, so the free Airport Express shuttle and Kowloon taxi-stand details couldn't be verified.","highlights":["Sasa Inn is licensed as Hotel/Guesthouse H/6290 (tel 5125 0008). The address matches the one in the app.","The building's official English name is Tsim Sha Tsui Mansion. Show taxi drivers the Chinese address 彌敦道87號華源大廈C座8字樓."],"tips":["Paying with Octopus saves HK$10 per adult on this fare.","Use the Chinese address in the app's Show card for the taxi."],"sources":[{"label":"HKIA – Airport Express fares and frequency","url":"https://www.hongkongairport.com/en/transport/to-from-airport/airport-express.page"},{"label":"Tourists.hk licensed-lodging directory – Sasa Inn H/6290","url":"https://www.tourists.hk/listing/h-6290.html"}]},"8":{"title":"Tsim Sha Tsui Harbourfront Walk","hours":"Promenade always open. The WinterFest TST light show runs 7–11 PM. A Symphony of Lights ended with its final show on Nov 18, 2026.","cost":"Free.","highlights":["Avenue of Stars: a 400 m harbour promenade with plaques, handprints and statues of Bruce Lee, Jackie Chan and Anita Mui.","Next to it on the Hung Hom Bypass is the 250 m Sports Wall of Fame, with portraits of 40+ Hong Kong Olympic and Asian Games medallists.","At dusk the Hong Kong Island skyline lights up across the harbour."],"tips":["HKTB recommends dusk for the day-to-night transition, which fits the 5:15 PM start.","The TST Winter Wonderland show starts at 7 PM on the TST harbourfront — it has replaced A Symphony of Lights."],"sources":[{"label":"HKTB – Avenue of Stars","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-avenue-of-stars.html"},{"label":"Tourism Commission – A Symphony of Lights special announcement (final show Nov 18, 2026)","url":"https://www.tourism.gov.hk/symphony/english/SpecialAnnouncements/SpecialAnnouncements.html"}]},"9":{"title":"Mak Man Kee Wonton Noodles — Jordan","hours":"Daily 12:00 noon – 12:30 AM. Closed Tuen Ng, Mid-Autumn and Lunar New Year days 1–3, none of which fall on Dec 8.","getThere":"G/F, 51 Parkes Street, Jordan (白加士街51號地下), at MTR Jordan Exit C2. Tel 2736 5561.","watch":"Dish prices couldn't be verified as text from an official source.","highlights":["Started in 1958 as a dai pai dong. Known for handmade wonton noodles brought from Guangzhou by founder Mak Woon-chi. Michelin Bib Gourmand.","Kwun Chung Market and Bowring Street Market are a short walk away if you want more to eat."],"tips":["The official menu (2025) is posted only as images on mmk.hk; check it there or in the shop.","Arriving around 6:30 PM is ahead of the busiest dinner hour. The app's 15-minute queue rule still applies."],"sources":[{"label":"Mak Man Kee official – contact and hours","url":"https://www.mmk.hk/contact-mmk"},{"label":"HKTB – Mak Man Kee Noodle Shop","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-mak-man-kee-noodle-shop.html"},{"label":"Mak Man Kee official – menu page","url":"https://www.mmk.hk/menu-mmk"}]},"10":{"title":"Temple Street / Yau Ma Tei Night Walk","hours":"Temple Street between Jordan Road and Kansu Street is closed to cars 2 PM – midnight. Most stalls set up around 4 PM; busiest after dark until about 10–11 PM.","cost":"Free to walk.","watch":"Dai pai dong menus lean on seafood. Some stalls stay open past midnight depending on the day and weather.","highlights":["Street food near the Temple Street archway: claypot rice, fish balls, siu mai, plus pepper cakes, spicy skewers, Turkish lamb and Pakistani dishes.","Impromptu Cantonese opera performances and fortune-teller stalls.","Photo stops: the archway, Tin Hau Temple at Yau Ma Tei, and the retro Mido Cafe."],"tips":["Skewers, lamb or a seafood plate if you are still hungry after noodles.","Fortune tellers and opera singers usually appear later in the evening, so the end of this 7:30–8:20 PM walk is when they start to appear."],"sources":[{"label":"HKTB – Temple Street Night Market","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-temple-street-night-market.html"},{"label":"Temple Street Night Market guide – opening hours","url":"https://www.temple-street-night-market.hk/opening-hours"}]},"11":{"title":"Winter Wonderland in Tsim Sha Tsui","hours":"18 Nov 2026 – 5 Jan 2027, 7–11 PM daily. Dec 8 uses the normal schedule; late shows to 1 AM run only on 24–27 Dec and 1–2 Jan.","getThere":"MTR to Tsim Sha Tsui or East Tsim Sha Tsui, then walk to the Hong Kong Cultural Centre precinct on the waterfront.","watch":"HKTB says the schedule can change without notice. Shows are partly suspended 28–30 Dec and fully on 31 Dec, which doesn't affect Dec 8.","highlights":["First edition of Prudential Hong Kong Winter Wonderland in TST: projection mapping, synchronised music and storytelling across the Cultural Centre, Museum of Art and Space Museum, themed as a northern-lights Christmas concert.","Best viewing: the Viewing Deck at the Hong Kong Cultural Centre, or outside the Museum of Art and Space Museum."],"tips":["The 8:30 PM visit sits well inside the 7–11 PM show hours.","WinterFest also has a 22 m tree and a 360° light-and-sound show at Statue Square Gardens, Central (same dates) if you want another evening."],"sources":[{"label":"HKTB – Prudential Hong Kong Winter Wonderland in Tsim Sha Tsui","url":"https://www.discoverhongkong.com/eng/events/hong-kong-winterfest/winter-wonderland-in-tsim-sha-tsui.html"},{"label":"HKTB – Hong Kong WinterFest 2026","url":"https://www.discoverhongkong.com/eng/what-s-new/events/hong-kong-winterfest.html"}]},"12":{"title":"Promenade, Dessert or an Arcade","hours":"Silvercord Amusement & Games: 08:00–02:00. Retrocity Concept: 10:00–02:00. NAMCO branches close by 22:00–22:30 and none are in TST.","getThere":"Silvercord Amusement & Games: Shop B03, Silvercord, 30 Canton Road, TST (tel 2730 3632). Retrocity Concept: LG23, Houston Centre, 63 Mody Road, TST (tel 6576 6680).","watch":"Arcade hours come from a 2024 guide and a directory that marks them 'pending verification'. Playspot lists Retrocity's building as Hoi Sun Centre; the street number is the same.","highlights":["Silvercord: 16 linked Wangan Midnight Maximum Tune 5 / Initial D racing simulators, an original Taiko no Tatsujin, and Hatsune Miku rhythm games.","Retrocity Concept: a non-smoking retro arcade with classic video games, maimai DX, Drum Mania and Z Gundam, and retro games for sale."],"tips":["Silvercord on Canton Road is the closer arcade to the Cultural Centre waterfront.","If you are short on protein, pick something up at a 7-Eleven on the way back, as the day plan suggests."],"sources":[{"label":"Honeycombers – arcades and game centres in Hong Kong","url":"https://thehoneycombers.com/hong-kong/game-arcades-game-centres-hong-kong/"},{"label":"Playspot – Silvercord Amusement & Games","url":"https://playspot.com.hk/en/venue/silvercord-amusement-games-248"},{"label":"Playspot – Retrocity Concept","url":"https://playspot.com.hk/en/venue/retrocity-concept-249"},{"label":"NAMCO Hong Kong – branch list and hours","url":"https://www.namco.com.hk/shop"}]}}},"day-12":{"checked":"2026-11-11","items":{"0":{"title":"Star Ferry: Tsim Sha Tsui → Central","hours":"Central ↔ TST runs 06:30–23:30. Weekday (Wed 9 Dec) frequency: every 6 min until ~09:45–09:55, then every 6–8 min until ~20:30–20:40, then every 10–12 min.","cost":"Adult, Monday–Friday (excl. public holidays): upper deck HK$5.0, lower deck HK$4.0. Four-Day Tourist Pass HK$50 (unlimited Central–TST and Wan Chai–TST rides for 4 days).","getThere":"Tsim Sha Tsui Star Ferry Pier on Salisbury Road by the Clock Tower; tap Octopus at the gate. Arrives at Central Star Ferry Pier, next to ifc mall and Hong Kong Station.","watch":"No eating or drinking on board; no standing on the upper deck until docked. Bags limited to 40 × 40 × 17.5 cm. Sailing times can vary with marine traffic and weather.","highlights":["Upper deck costs HK$1 more than the lower deck on weekdays (HK$5.0 vs HK$4.0); no reserved seating — sit anywhere.","Central pier side: Central Harbourfront Promenade and the Hong Kong Observation Wheel are beside the pier."],"tips":["Octopus is simplest. Cash is HKD only: HK$10/HK$20 notes and coins, change given. Self-service machines take credit cards, Alipay, WeChat Pay and UnionPay QuickPass and issue one ticket per person.","The Four-Day Tourist Pass is sold only at the TST pier Control Centre (near Mammy Pancake).","TST pier has a 7-Eleven, % Arabica and restrooms if you need a pre-crossing stop."],"sources":[{"label":"Star Ferry: routes, timetable, fares, payment, passenger notice","url":"https://www.starferry.com.hk/en/service"},{"label":"Star Ferry: piers and facilities","url":"https://www.starferry.com.hk/en/pier"}]},"1":{"title":"Central / Sheung Wan Compact Urban Route","cost":"Free to walk. Tourist reward (27 Jul–31 Dec 2026): spend HK$200+ in one same-day transaction at participating Old Town Central merchants for a limited-edition Street Sign Pin, while stocks last.","getThere":"From Central Star Ferry Pier walk inland to Queen's Road Central. Old Town Central is bounded by Wyndham Street, Possession Street, Queen's Road Central and Caine Road; Sheung Wan's dried-goods streets are just west.","watch":"The escalator does not reach The Peak (HKTB states this explicitly).","highlights":["Hollywood Road: galleries, cafés, murals and heritage sites; HKTB notes Time Out ranked it the world's second-coolest street.","Central–Mid-Levels Escalator: 800 m covered system from Queen's Road Central to Conduit Road, 16 escalators plus 3 travelators.","Dried Seafood & Tonic Food Street (Des Voeux Road West, Wing Lok Street, Bonham Strand West): shop fronts of dried scallops, shrimp, fish maw, ginseng, dried berries and roots — a look-only street."],"tips":["The escalator runs DOWNHILL 06:00–10:00 and uphill only from 10:20 — during this 9–10 AM slot walk the stairs beside it.","Pick up a free Old Town Map (street-sign designs) while stocks last."],"sources":[{"label":"HKTB: Old Town Central","url":"https://www.discoverhongkong.com/eng/explore/neighbourhoods/old-town-central.html"},{"label":"HKTB: Central–Mid-Levels Escalator","url":"https://www.discoverhongkong.com/eng/place-to-go/attractions/central-mid-levels-escalator.html"},{"label":"HKTB: Dried Seafood Street & Tonic Food Street","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-dried-seafood-street-and-tonic-food-street.html"}]},"2":{"title":"Climb to the Peak → Lugard Road → High West","hours":"Public roads and country-park trail; no gates. Go in daylight.","cost":"Free","getThere":"Old Peak Road climbs from the Robinson Road junction (Mid-Levels) to Victoria Gap; the upper part is a pedestrian-only slope. From the Peak Tower, Lugard Road starts the AFCD Peak Trail (High West Section); High West is a branch off it.","watch":"AFCD: Lugard Road edges and the High West cliffs are weathered and steep — stay on the road/built path and never cross railings. If cloud covers the Peak, views vanish (see rain plan).","highlights":["Old Peak Road was the original route to the summit (built 1920s, formerly 'Peak Road'); one of six surviving Victoria City Boundary Markers stands on it.","Lugard Road (built 1913–14): century-old plank-road sections over the cliff with the classic Victoria Harbour panorama; Lugard Road Lookout is at 31 Lugard Road, ~20 min from the Peak Tower.","High West viewing point (AFCD): 180° view west over Tsing Yi, Lantau and Lamma; AFCD also lists the High West artillery observation post (西高山砲兵觀察所) nearby."],"tips":["AFCD rates the full Peak Trail (High West Section) 4 km / 2.5 h, difficulty 2 of 5 (普通); doing just Lugard Road + the High West spur and returning is shorter.","The whole Peak Circle Walk loop (Lugard + Harlech Roads) is 3.5 km and about 1 hour per HKTB.","Water/food only at Peak Tower, Peak Galleria, and a kiosk in Victoria Peak Garden — none on Lugard Road or High West.","Check HKO's Hiking Trail Weather Service before climbing."],"sources":[{"label":"AFCD hiking.gov.hk: Peak Trail (High West Section)","url":"https://www.hiking.gov.hk/trail/info/id/dDI5eDQrbTBHemxIaTEvKzh6N3hwdz09"},{"label":"AFCD Enjoy Leisure: Peak Trail (High West Section)","url":"https://enjoyleisure.afcd.gov.hk/en/activities/fisheries/peak-trail-high-west-section-87"},{"label":"HKTB: Peak Circle Walk","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-peak-circle-walk.html"},{"label":"Wikipedia: Old Peak Road (route/history)","url":"https://en.wikipedia.org/wiki/Old_Peak_Road"}]},"3":{"title":"Taxi Down to Wan Chai","cost":"Red urban taxi: HK$29 for the first 2 km, then HK$2.1 per 200 m (or per minute waiting) until the meter reaches HK$102.5, HK$1.4 thereafter. HK$6 per bag carried in the boot.","getThere":"Pick up near Peak Tower / Peak Galleria; ask for 希慎廣場 Hysan Place, 500 Hennessy Road, Causeway Bay. Public-transport fallback: bus 15 / X15 or green minibus 1 from Peak Galleria to Central, then MTR Island Line Central → Causeway Bay.","tips":["Ask for a machine-printed receipt; drivers must issue one on request.","Carry small notes: drivers are not obliged to change HK$500/HK$1,000."],"sources":[{"label":"Transport Department: taxi fares","url":"https://www.td.gov.hk/en/transport_in_hong_kong/public_transport/taxi/taxi_fare_of_hong_kong/index.html"},{"label":"HKTB: Peak Circle Walk (leaving The Peak)","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-peak-circle-walk.html"},{"label":"MTR system map (Island Line stations)","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"}]},"5":{"title":"Causeway Bay → Happy Valley on Foot and by Tram","cost":"Tram adult HK$3.30 flat fare.","getThere":"Board a tram showing 'Happy Valley' — route 2 (Happy Valley ↔ Shau Kei Wan) or route 5 (Kennedy Town ↔ Happy Valley) — and ride to the Happy Valley terminus beside the racecourse on Wong Nai Chung Road.","watch":"From 1.5 h before the first race, Wong Nai Chung Road southbound (Queen's Road East → racecourse) closes to most traffic, so road travel around the course slows.","tips":["Pay when you exit at the FRONT door: Octopus, Visa/Mastercard/UnionPay/JCB/Amex contactless, Apple/Google Pay, or QR (AlipayHK, WeChat Pay). No change for cash.","Aim to reach the racecourse gates as they open; on a nine-race night they may open earlier than two hours before race 1 (see index 6)."],"sources":[{"label":"Hong Kong Tramways: schedules and fares","url":"https://www.hktramways.com/en/schedules-fares/"},{"label":"HKJC: special traffic arrangements, Happy Valley race meetings","url":"https://corporate.hkjc.com/corporate/corporate-news/english/2022-11/news_2022112901842.aspx"}]},"7":{"title":"Happy Valley — International Jockeys' Championship","hours":"LONGINES IJC confirmed for Wed 9 Dec 2026, Happy Valley night meeting (9 turf races, 1000–1800 m). First race 6:40 or 7:10 PM (card not yet published); gates open 2 h before race 1, earlier when >8 night races. Last race ~11:00 PM.","cost":"Public Enclosure: free for visitors 18+ with a valid passport/travel document (otherwise HK$10 by Octopus). Members Enclosure Tourist Badge on IJC night: HK$190 (passport required at purchase).","getThere":"Public Enclosure entrance on Wong Nai Chung Road (HKJC names entrance G for the HK$10 Octopus gate).","watch":"No entry under 18. Public Enclosure bans slippers, flip-flops, plastic footwear and offensive clothing; Members Enclosure also bans singlets and sports shorts. HKJC says start times are provisional and may change; check the race card once published.","highlights":["IJC format: elite local and overseas jockeys ride four designated races; highest points total wins. Ride allocation is drawn on 7 Dec, press conference 8 Dec.","HKJC top spots: Parade Ring, 1650 m starting gate, Winning Post, Beer Garden food trucks, centre-stage live bands; Racing Academy and virtual-ride simulator on 1/F, Grandstand Gate G.","2/F Track View Terrace has a sweeping track view plus a big screen showing races from multiple angles (HKTB)."],"tips":["Final two IJC places are decided after the 25 Nov meeting; check the HKIR event hub for the full jockey line-up.","HKJC suggests arriving by 9:30 PM at the latest; earlier is better on a big night.","Free Wi-Fi: network 'HKJC'."],"sources":[{"label":"HKJC: LONGINES HKIR event hub (IJC 9 Dec, key dates)","url":"https://campaigns.hkjc.com/racing-event-hub-hkir/en/"},{"label":"HKJC Happy Wednesday: LONGINES IJC admission & hours","url":"https://happywednesday.hkjc.com/en-US/parties/S2627LonginesIJC/"},{"label":"HKJC: Happy Valley Racecourse visit page","url":"https://entertainment.hkjc.com/en-us/visit-us/happy-valley-racecourse"},{"label":"HKJC: December 2026 fixture","url":"https://racing.hkjc.com/en-us/local/information/fixture?calyear=2026&calmonth=12"}]},"9":{"title":"Back to TST","cost":"Taxi to Kowloon adds the Cross-Harbour Tunnel charge: HK$25 toll + HK$25 return toll (return toll waived only from a cross-harbour taxi stand).","getThere":"MTR: walk to Causeway Bay station, Island Line west to Admiralty, change to Tsuen Wan Line to Tsim Sha Tsui (hotel is at Exit C2). Alternative: Star Ferry Central → TST runs until 23:30.","tips":["The Sung Tak Street taxi stand is suspended 5:00–11:59 PM on night meetings; a temporary stand on Wong Nai Chung Road (south of the Members' entrance) runs only from race 3 until the end of the second-last race."],"sources":[{"label":"HKJC: special traffic arrangements (taxi stands)","url":"https://corporate.hkjc.com/corporate/corporate-news/english/2022-11/news_2022112901842.aspx"},{"label":"Transport Department: taxi fares & tunnel tolls","url":"https://www.td.gov.hk/en/transport_in_hong_kong/public_transport/taxi/taxi_fare_of_hong_kong/index.html"},{"label":"MTR system map","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"},{"label":"Star Ferry: timetable","url":"https://www.starferry.com.hk/en/service"}]},"10":{"title":"Late Arcade / Dessert in TST","getThere":"From Tsim Sha Tsui MTR (Tsuen Wan Line) — the hotel exit C2 is the base.","watch":"No specific TST arcade with late opening hours could be verified for 9 Dec; confirm hours on the spot before walking over.","tips":["Decide at the racecourse: if you stay to the final race (~11:00 PM), this slot realistically shrinks to a quick dessert near the hotel."],"sources":[{"label":"HKJC Happy Wednesday: race-night hours (last race ~11 PM)","url":"https://happywednesday.hkjc.com/en-US/parties/S2627LonginesIJC/"},{"label":"MTR system map","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"}]}}},"day-13":{"checked":"2026-11-11","items":{"0":{"title":"Taxi / MTR to the Lion Rock Approach","cost":"Urban (red) taxi: HK$29 for the first 2 km, then HK$2.1 per 200 m or per minute waiting until the meter reaches HK$102.5, HK$1.4 after; HK$6 per boot bag; HK$8 surcharge if routed via Lion Rock Tunnel.","getThere":"HKTB route note: MTR to Wong Tai Sin or Diamond Hill, then taxi up Sha Tin Pass Road to the Lion Pavilion (start of MacLehose Trail Section 5). From TST: Tuen Ma Line East Tsim Sha Tsui → Hung Hom → Ho Man Tin → To Kwa Wan → Sung Wong Toi → Kai Tak → Diamond Hill.","watch":"Drivers can legally refuse change for HK$500/HK$1,000 notes — carry small bills or Octopus.","highlights":["Sha Tin Pass was the old footpath between Sha Tin and Tsz Wan Shan; the trailhead sits at the pass on Sha Tin Pass Road.","AFCD: a small village store at Shatin Pass sells cold drinks — the last resupply before the ridge."],"tips":["Say 沙田坳道 獅子亭 (Lion Pavilion) to the driver; a red urban taxi is the right type for Kowloon.","Ask for a printed receipt — drivers must issue one on request; they are not required to change HK$500/1,000 notes."],"sources":[{"label":"Hello! Hong Kong (HKTB content): Sha Tin Pass Road route","url":"https://www.hellohongkong.com.hk/blog/sha-tin-pass-road-to-kowloon-reservoir"},{"label":"Transport Department: taxi fares","url":"https://www.td.gov.hk/en/transport_in_hong_kong/public_transport/taxi/taxi_fare_of_hong_kong/index.html"},{"label":"AFCD: Lion Rock Country Park","url":"https://www.afcd.gov.hk/english/country/cou_vis/cou_vis_cou/cou_vis_cou_lr/cou_vis_cou_lr.html"},{"label":"MTR system map & station list","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"}]},"1":{"title":"Lion Rock Hike","hours":"Country park trail, no gate hours. Go in daylight; the path is unlit.","cost":"Free","getThere":"From Sha Tin Pass (MacLehose Trail Section 5) climb west to the ridge (~1.5–2 km, ~200 m gain to the summit), then descend the AFCD-restored stone trail from Lion Rock Pass down to Wang Tau Hom / Wong Tai Sin.","watch":"Ridge is exposed and the scramble is hazardous when wet or windy. Macaques live in the park (mainly near Tai Po Road): never feed them; keep food packed.","highlights":["Lion Rock summit 495 m: the 'lion's head' faces west over all of Kowloon, Victoria Harbour and the New Territories.","Reunification Pavilion on the mid-slope: open views of east Kowloon and the old Kai Tak runway (today's cruise terminal) — preview of the afternoon.","Qing-era stone trails on both flanks were the old Sha Tin–Kowloon routes."],"tips":["Final 50–70 m to the lion's head is a hands-on rock scramble; stow poles. Stop at the main ridge if the rock is wet.","No water on the trail: carry 1–1.5 L each; the Shatin Pass store is the only top-up.","Emergency: 999 or 112; quote the nearest distance post number (e.g. M0xx on the MacLehose Trail)."],"sources":[{"label":"AFCD: Lion Rock Country Park","url":"https://www.afcd.gov.hk/english/country/cou_vis/cou_vis_cou/cou_vis_cou_lr/cou_vis_cou_lr.html"},{"label":"Hong Kong Trip: Lion Rock hike guide","url":"https://www.hongkong-trip.com/guides/lion-rock-hike-guide/"},{"label":"HKTB: hiking safety (emergency, distance posts)","url":"https://www.discoverhongkong.com/eng/outdoors/top-10-easy-hikes.html"},{"label":"TGR: Lion Rock route overview","url":"https://tgr.run/routes/lion-rock-hiking-guide"}]},"2":{"title":"Finish Wang Tau Hom / Tsz Wan Shan Side → Taxi to Kowloon Walled City Park","cost":"Taxi on the urban meter (HK$29 flag, HK$2.1 per 200 m); MTR by Octopus.","getThere":"The Wang Tau Hom trail ends ~8–12 min walk from Wong Tai Sin MTR Exit D3 (Ching Tak Street). Taxi from there, or MTR: Kwun Tong Line Wong Tai Sin → Diamond Hill, change to Tuen Ma Line → Kai Tak → Sung Wong Toi, Exit B3, then ~8 min walk to the park.","tips":["MTR is a reliable fallback if taxis are scarce: Sung Wong Toi Exit B3 is the station exit MTR names for the park.","Buy water at the convenience stores near Wong Tai Sin station after the descent."],"sources":[{"label":"Hong Kong Trip: Wong Tai Sin approach (Exit D3)","url":"https://www.hongkong-trip.com/guides/lion-rock-hike-guide/"},{"label":"LCSD: Kowloon Walled City Park — Getting Here","url":"https://www.lcsd.gov.hk/en/parks/kwcp/access.html"},{"label":"MTR: Kai Tak / Sung Wong Toi discoveries","url":"https://www.mtr.com.hk/en/customer/main/discover-tkw-swt-huh.html"},{"label":"Transport Department: taxi fares","url":"https://www.td.gov.hk/en/transport_in_hong_kong/public_transport/taxi/taxi_fare_of_hong_kong/index.html"}]},"3":{"title":"Kowloon Walled City: A Cinematic Journey (If a Slot Is Free)","hours":"Park daily 6:30 AM – 11:00 PM. Film-set exhibition daily 9:00 AM – 7:00 PM, 24 May 2025 – 23 May 2028. Since 1 Sep 2026: Mon–Fri 9 AM–12 noon = 2 sessions of 25 min per hour; all other hours = 3 sessions of 15 min per hour.","cost":"Free","getThere":"MTR Sung Wong Toi Exit B3, ~8 min walk. Entrance area: Tung Tsing Road / Carpenter Road. Ticket counter is in front of the Yamen.","watch":"Max 60 visitors inside at once. Closed under Black Rainstorm or Signal No. 8+; reopens within 2 h of cancellation if conditions permit. Staff may shift session start times.","highlights":["Sets from Twilight of the Warriors: Walled In, installed inside the restored Qing Yamen.","Free outdoor display at the South Gate: bronze model of a pre-demolition Walled City building and a cross-section shadow wall.","Old South Gate remains and Yamen are the genuine surviving fabric; the film set is reconstruction."],"tips":["Same-day tickets: morning sessions (9 AM–before 2 PM) from 8:45 AM; afternoon (2–7 PM) from 1:45 PM; max 2 tickets per person per collection, first come first served.","Arriving ~11:30 Thu: slots before noon are 25 min; from 12:00 they shrink to 15 min.","Enter at the printed time — late tickets are void; remaining places go to the standby queue."],"sources":[{"label":"LCSD: Opening Hours and Admission","url":"https://www.lcsd.gov.hk/en/parks/kwcp/opening.html"},{"label":"LCSD: A City of Thousand Faces / exhibition rooms","url":"https://www.lcsd.gov.hk/en/parks/kwcp/fac/thousand.html"},{"label":"LCSD: Getting Here","url":"https://www.lcsd.gov.hk/en/parks/kwcp/access.html"},{"label":"HKTB: Kowloon Walled City Park","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kowloon-walled-city-park.html"}]},"5":{"title":"Walk East: Sung Wong Toi → Kai Tak Waterfront → Sports Park","hours":"Sung Wong Toi station archaeology display: same as station opening hours.","cost":"Free","getThere":"Kowloon City → Sung Wong Toi Garden (inscribed rock) → Sung Wong Toi station concourse (Exit D side) → Kai Tak Sports Park, 38 Shing Kai Road; MTR Kai Tak and Sung Wong Toi stations are each within ~10 min walk of the park.","highlights":["Sung Wong Toi Garden: the 'Terrace of the Song Emperors' inscription, cut from Sacred Hill in 1956 when the hill was levelled for Kai Tak Airport.","'Treasures from Sacred Hill' in Sung Wong Toi station: 500+ Song–Yuan finds (porcelain, tea bowls, coins) unearthed 2012–2015; display renewed March 2024.","Kai Tak Sports Park on the old airport tarmac: 50,000-seat Stadium with retractable roof, 10,000-seat Arena, 5,000-seat Youth Sports Ground (free when not in use)."],"tips":["The garden, station display and park are three separate places with separate entrances — pin each one.","Kai Tak Mall inside the park is the indoor fallback if it rains."],"sources":[{"label":"AMO: Archaeological Display at Sung Wong Toi Station","url":"https://www.amo.gov.hk/en/visitor-centre/exhibitions/sung-wong-toi-station/index.html"},{"label":"MTR: Kai Tak / Sung Wong Toi discoveries","url":"https://www.mtr.com.hk/en/customer/main/discover-tkw-swt-huh.html"},{"label":"HKTB: Kai Tak Sports Park","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kai-tak-sports-park.html"},{"label":"HomeHK: Walled City / Sung Wong Toi half-day","url":"https://homehk.org/en/guides/hk-kowloon-walled-city-sung-wong-toi"}]},"6":{"title":"Kai Tak Buffer — JOYPOLIS SPORTS (Backup Only)","hours":"Regular days: all floors 10:30 AM – 6:30 PM; 3/F Future Arena to 8:30 PM. Peak days: all floors 10:30 AM – 8:30 PM. Last entry 6:30 PM. Check the business calendar for whether Thu Dec 10 is Regular or Peak.","cost":"Regular day JPS Pass 60 min: HK$180 (age 12+). Peak day 120-min fixed sessions: HK$360 adult. Grip socks HK$30/pair if needed.","getThere":"G/F–4/F, Health and Wellness Centre, Kai Tak Sports Park. MTR Sung Wong Toi Exit D or Kai Tak Exit D, each within a 10-min walk. Taxi stand: G/F Kai Tak Mall 2.","watch":"Tickets are date-specific, non-refundable and non-reschedulable. Private events can close time slots — check the notice on the ticketing site. Closed under Signal No. 8+ or Black Rainstorm.","highlights":["G/F Ninja Dojo: ninja obstacle courses and shuriken laser battles.","2/F SONIC Stadium: SEGA-licensed Sonic sports challenges (incl. treadmill race game).","3/F Future Arena: MR lava game, VR horse racing, AR climbing wall.","4/F Hungry Tiger Hidden Dragon restaurant: 270° views over Kai Tak."],"tips":["Book online (quotas limited) and arrive 20 min early to redeem wristbands; sign the online waiver beforehand to speed entry.","A 2:15 PM entry on a Regular day gets all floors; after 6:30 PM only 3/F runs."],"sources":[{"label":"JOYPOLIS SPORTS ticketing (hours, calendar)","url":"https://ticketing.hk-joypolis-sports.com/en/"},{"label":"JOYPOLIS SPORTS: Ticket prices & T&Cs","url":"https://hk-joypolis-sports.com/ticket"},{"label":"JOYPOLIS SPORTS: Access","url":"https://hk-joypolis-sports.com/en/access"},{"label":"HKTB: JOYPOLIS SPORTS HONG KONG","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-joypolis-sports.html"}]},"7":{"title":"Early Dinner at Kai Tak","getThere":"Inside Kai Tak Sports Park (38 Shing Kai Road): Kai Tak Mall 1/2/3 next to the Arena.","highlights":["Ming Garden (M2-310, 3/F Kai Tak Mall 2): char siu, suckling pig, dim sum; window seats face Kai Tak Stadium.","So Gor Beef Brisket (M3-107, 1/F Mall 3): signature braised outer skirt; brisket, short rib, tendon noodles.","Gyu-Kaku J (M2-301, 3/F Mall 2): budget yakiniku sets grilled at the table — easy protein.","N+ Burger (M2-102, 1/F Mall 2): Angus burgers in old-Kai-Tak-airport decor.","Food Gala (2/F Mall 1): 10 counters incl. Pepper Lunch Express and JMT Korean — fastest option."],"tips":["Eat by ~5:15 so you clear security and find seats before your session (about 6:00 PM expected; the ticket time rules).","Food Gala is the low-queue fallback if sit-down places are full before the session."],"sources":[{"label":"HKTB: Exciting Eats at Kai Tak Sports Park","url":"https://www.discoverhongkong.com/eng/food-and-drink/exciting-eats-at-kai-tak-sports-park-and-beyond.html"},{"label":"DinkStart: Kai Tak Arena logistics (food court)","url":"https://dinkstart.com/hong-kong-slam-2026/getting-there"}]},"8":{"title":"WTT Finals Hong Kong — Kai Tak Arena (Ticketed Session)","hours":"Thu Dec 10, 18:00 = Session 04: Women's Singles R16 + Men's Singles R16 + Mixed Doubles QF. (Session 03 is 12:00 the same day.) Event runs Dec 9–13.","cost":"Sessions 1–4: HK$880 / HK$680 (CAT 2) / HK$480 / HK$300, plus HK$35 customer service fee per ticket.","getThere":"Kai Tak Arena (10,000-seat indoor hall), Kai Tak Sports Park, Shing Kai Road. MTR Tuen Ma Line to Kai Tak Exit D or Sung Wong Toi Exit D, ~5–10 min walk; follow signs for the Arena, not the Stadium.","watch":"Schedule and order of play are subject to change by the organiser. Session end time was not published on the sources checked.","highlights":["Season-ending event: 16 top men's and women's singles players plus mixed doubles.","A Thursday evening Round-of-16 session packs many matches across three events into one ticket."],"tips":["Central side-on seats matter more than category in a 10,000-seat arena.","Bags are screened at the park entrance; check the park-rules page for prohibited items before going."],"sources":[{"label":"DotDotNews: WTT HK Finals dates & ticket prices","url":"https://english.dotdotnews.com/a/202610/20/AP6ad6d045e4b02fd1c5f51358.html"},{"label":"Koobit: WTT Finals Hong Kong session schedule","url":"https://www.koobit.com/wtt-finals-hong-kong-e73000"},{"label":"HKTB: Kai Tak Sports Park (Arena capacity)","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kai-tak-sports-park.html"},{"label":"DinkStart: getting to Kai Tak Arena","url":"https://dinkstart.com/hong-kong-slam-2026/getting-there"}]},"9":{"title":"Late Dinner → Back to TST","getThere":"Kai Tak Exit D → Tuen Ma Line towards Tuen Mun: Kai Tak → Sung Wong Toi → To Kwa Wan → Ho Man Tin → Hung Hom → East Tsim Sha Tsui (5 stops). Sung Wong Toi (also Exit D) can be calmer when a session empties.","watch":"Taxi pick-up zones change on event days and queue right after sessions; the MTR is usually faster at that moment.","highlights":["Kowloon City's Thai quarter is a short taxi from the park for a late meal (see lunch list).","Kai Tak Mall has 60+ food and drink outlets if you'd rather eat on site."],"tips":["During major events MTR runs crowd management and adds trains — no need to rush; don't stop or meet up inside the station.","Have Octopus or a contactless card ready before the gates."],"sources":[{"label":"MTR: Kai Tak Sports Park travel tips","url":"https://www.mtr.com.hk/en/customer/main/kaitak-sports-park-mtr.html"},{"label":"MTR system map & station list","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"},{"label":"DinkStart: Kai Tak Arena logistics","url":"https://dinkstart.com/hong-kong-slam-2026/getting-there"}]},"10":{"title":"TST Arcade / Dessert (If Still Awake)","highlights":["Verified dessert alternative if you eat in Kowloon City instead: Chiu Chow Hop Shing Dessert (9 Lung Kong Rd) — ~70 years, 90 varieties incl. black sesame dumplings.","Tei Mou Koon Dessert (G/F, 47 Fuk Lo Tsun Rd, Kowloon City): walnut, black sesame, almond and lotus seed sweet soups."],"tips":["No TST arcade or dessert shop hours were verified in this pass — confirm on the spot before walking far.","Kowloon City is a short taxi or bus hop from the park, so dessert there before riding back to TST is an option."],"sources":[{"label":"HKTB: Top Dining Hotspots in Kowloon City","url":"https://www.discoverhongkong.com/eng/neighbourhoods/kowloon-city/dining-hotspots-in-kowloon-city.html"},{"label":"DinkStart: eating around Kai Tak","url":"https://dinkstart.com/hong-kong-slam-2026/getting-there"}]}}},"day-14":{"checked":"2026-11-11","items":{"0":{"title":"MTR: TST → Tung Chung","getThere":"Tsuen Wan Line (red) from Tsim Sha Tsui towards Tsuen Wan, change at Lai King to the Tung Chung Line (orange) and ride to Tung Chung, the terminus. Tung Chung Line stops: Lai King → Tsing Yi → Sunny Bay → Tung Chung.","tips":["NLB buses leave from Tung Chung Station Bus Terminus on Tat Tung Road, next to the MTR station; have Octopus loaded for the bus too.","Fri Dec 11 is a weekday, so NLB charges the lower weekday fares all day."],"sources":[{"label":"MTR system map & line station lists","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"},{"label":"NLB route 11 Tung Chung → Tai O (terminus & stops)","url":"https://www.nlb.com.hk/en/route/13"}]},"1":{"title":"Taxi to Pak Kung Au","cost":"NLB route 11, weekday fare HK$14.0 from Tung Chung Station Bus Terminus (holiday fare HK$23.3).","getThere":"NLB 11 (Tung Chung Station Bus Terminus → Tai O) calls at the 'Pak Kung Au' stop on Tung Chung Road, the 15th stop. Mon–Sat departures around your window: 07:50, 08:00, 08:15, 08:30, 08:45, 09:05.","watch":"Route 11 fares are flat to Pak Kung Au (you pay the full HK$14.0 even though you leave early).","tips":["Ask the driver for 伯公坳 Pak Kung Au; it comes right after Tung Chung Au Management Centre.","The plan uses a taxi; if you take the bus, the 07:50 or 08:00 fits. The 08:15 and 08:30 trips detour via Tong Fuk Correctional Institution, which is beyond Pak Kung Au, so it does not affect you."],"sources":[{"label":"NLB route 11 Tung Chung → Tai O: stops, fares, timetable","url":"https://www.nlb.com.hk/en/route/13"}]},"2":{"title":"Lantau Peak: Pak Kung Au → Summit → Ngong Ping","hours":"Country park trail; no gate hours. HKTB: best hiked early morning, October–April.","cost":"Free","getThere":"Lantau Trail Section (Stage) 3: Pak Kung Au (Tung Chung Gap) → Lantau Peak 934 m → Ngong Ping. HKTB calls it the easiest route up: about 600 m of climbing over 4.5 km, typically 2.5 hours.","watch":"AFCD: the first five Lantau Trail stages follow rugged slopes and ridges and demand physical strength and experience. Respect the weather veto.","highlights":["Lantau Peak (Fung Wong Shan, 'Phoenix Mountain') is Hong Kong's second-highest summit and the high point of Lantau South Country Park.","Summit views over the South China Sea, outlying islands and, on clear days, the Hong Kong skyline.","In winter the slopes turn brown and gold; the descent drops you toward Ngong Ping and the Big Buddha."],"tips":["AFCD: the climb is steep and strenuous; carry a windbreaker, dry food and drinking water.","HKTB: winter is cooler and clearer but the peak can be windy; pack a layer for the summit.","The Kau Nga Ling 'Dog Teeth Range' alternatives are for experienced hikers only; stay on Stage 3."],"sources":[{"label":"Discover Hong Kong: Lantau Peak","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-lantau-peak.html"},{"label":"AFCD: Lantau South Country Park","url":"https://www.afcd.gov.hk/english/country/cou_vis/cou_vis_cou/cou_vis_cou_ls/cou_vis_cou_ls.html"}]},"3":{"title":"Big Buddha (20 min)","hours":"Tian Tan Buddha 10:00 AM – 5:30 PM daily; Po Lin Monastery 9:00 AM – 6:00 PM daily (incl. public holidays).","highlights":["Bronze seated Buddha on Mount Muk Yue at 482 m: 26.4 m with lotus seat, 34 m with the three-level base, 250 tonnes, cast in 202 bronze pieces.","Base platform halls are open: Hall of Merits (500-year-old nanmu Ksitigarbha), Hall of Realm of Reality, and the Memorial Hall with two Buddha relics.","Six bronze Deities circle the statue; look back over Po Lin Monastery and the South China Sea."],"tips":["Po Lin says expect a long flight of stone steps up to the statue; budget legs after the summit.","The 'Thus Come Thus Gone' renovation exhibition (10 AM – 5 PM, in front of the Buddha Hall) is optional; skip it to keep to 30 min."],"sources":[{"label":"Po Lin Monastery: visitor information & hours","url":"https://www.plm.org.hk/eng/visitors.php"},{"label":"Po Lin Monastery: Tian Tan Big Buddha","url":"https://www.plm.org.hk/eng/tour_buddha.php"},{"label":"Po Lin Monastery: Building the Big Buddha","url":"https://www.plm.org.hk/eng/buddha.php"}]},"4":{"title":"Quick Lunch at Ngong Ping","hours":"Po Lin Vegetarian Kitchen 11:30 AM – 4:30 PM daily.","highlights":["Po Lin Vegetarian Kitchen (left of the Main Shrine Hall): set meals sized to the table — typically a soup, a deep-fried dish and a vegetable dish with rice.","Snack shop next door: house-made bean curd dessert and mango glutinous rice dumplings (limited quantity).","Ngong Ping Village: a two-storey building with 20+ outlets from classic Hong Kong dishes to international food."],"tips":["Protein: the monastery meal is vegetarian; for meat, eat in Ngong Ping Village instead.","Enquiries at the Vegetarian Kitchen reception or the Big Buddha entrance; group bookings tel 2985 4736."],"sources":[{"label":"Po Lin Monastery: Vegetarian food","url":"https://www.plm.org.hk/eng/food.php"},{"label":"Discover Hong Kong: Ngong Ping Village","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-ngong-ping-village.html"}]},"5":{"title":"Bus 21: Ngong Ping → Tai O (1:20 PM)","hours":"Mon–Sat departures from Ngong Ping: 07:30, 10:35, 11:20, 12:20, 13:20, 14:20, 15:20, 16:20, 17:15, 17:45 (Sat only), 18:15.","cost":"Weekday fare HK$7.9 (holiday HK$19.2).","getThere":"Board at the Ngong Ping stop on Po Ngong Road (terminus). 15 stops via Keung Shan Road and Tai O Road to Tai O; journey time 18 minutes.","tips":["The target is 1:20 PM (on the Mon–Sat timetable); the next is 2:20 PM.","Sunday adds half-hourly extras (13:50, 14:50) — not relevant on Friday."],"sources":[{"label":"NLB route 21 Ngong Ping → Tai O","url":"https://www.nlb.com.hk/en/route/19"}]},"6":{"title":"Tai O — Stilt Houses, Waterfront, Food, Short Sampan","watch":"Sampan price and operating times are set by private operators and were not verifiable; agree the price before boarding.","highlights":["HKTB: a historic fishing village of winding canals, with local snacks and nearby hiking trails.","Walk the canals and waterfront, then graze the local snacks before the bus."],"tips":["Check the government 'Tai O Tourist Hotspots Pedestrian Information' platform for live crowd levels, camera feeds, weather and transport.","Bus 11 leaves from the Tai O stop on Tai O Road; be there 10 min before your departure."],"sources":[{"label":"Discover Hong Kong: Tai O","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-tai-o.html"},{"label":"NLB route 11 Tai O → Tung Chung","url":"https://www.nlb.com.hk/en/route/14"}]},"7":{"title":"Bus 11: Tai O → Tung Chung (3:45 PM)","hours":"Mon–Sat departures from Tai O: 16:10, 16:25, 16:35, 16:45, 16:55, 17:05, 17:15, 17:25, 17:35, 17:50, 18:05 … last 00:15.","cost":"Weekday fare HK$14.0 (holiday HK$23.3).","getThere":"Tai O stop (Tai O Road) → South Lantau Road (Shek Pik, Tong Fuk, Cheung Sha) → Pak Kung Au → Tung Chung Station Bus Terminus. Timetabled journey 52 minutes.","watch":"Some trips detour via Sha Tsui or Tong Fuk Correctional Institution and take longer; check the trip in the NLB app.","tips":["Mon–Sat departures from Tai O around your window: 3:30, 3:45, 4:00, 4:10 and 4:25 PM, so a missed bus costs 10–15 minutes.","The ride takes about 52 minutes, so the 3:45 PM bus reaches Tung Chung around 4:37 PM."],"sources":[{"label":"NLB route 11 Tai O → Tung Chung","url":"https://www.nlb.com.hk/en/route/14"}]},"10":{"title":"Winter Wonderland in Central","hours":"Christmas Town (18 Nov 2026 – 5 Jan 2027): Mon–Fri 4:00–11:30 PM, Sat–Sun 11 AM – 11:30 PM; lights on from 6 PM; last admission 30 min before closing. Light show 7–11 PM daily, every 30 minutes.","cost":"Free admission","getThere":"North and South Statue Square Gardens, Des Voeux Road Central. MTR Central station Exit K.","watch":"Crowd control may be imposed at peak periods; follow staff and police instructions.","highlights":["22-metre Christmas tree, interactive booths, a Hot Air Balloon Terminal and Christmas Express Station set.","Projection light show on the Bank of China Tower, HSBC Main Building, Mandarin Oriental, Court of Final Appeal, City Hall and more, viewed from the gardens."],"tips":["Light shows run on the hour and half-hour from 7 PM: catch the 7:00 show, walk Christmas Town, and the 7:30 show if you're still there.","Santa appears on selected days only."],"sources":[{"label":"Discover Hong Kong: Winter Wonderland in Central","url":"https://www.discoverhongkong.com/eng/events/hong-kong-winterfest/winter-wonderland-in-central.html"}]},"11":{"title":"Hong Kong Observation Wheel","hours":"Fri–Sun 11:00 AM – 11:00 PM; Mon–Thu 12:00–10:00 PM; last admission 30 min before closing (10:30 PM on Friday).","cost":"Adult HK$20; concession HK$10; private gondola HK$160.","getThere":"33 Man Kwong Street, Central Harbourfront, inside AIA Vitality Park.","highlights":["60 m tall with 42 air-conditioned gondolas; the ride lasts about 15–20 min (two to three rotations).","Views over Victoria Harbour, Central's towers, the Star Ferry pier and Kowloon's lights."],"tips":["Book online to skip the ticket queue.","The site publishes separate weather arrangements; check them if wind or rain picks up."],"sources":[{"label":"Hong Kong Observation Wheel (official)","url":"https://www.hkow.hk/"},{"label":"Discover Hong Kong: The Hong Kong Observation Wheel","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-the-hong-kong-observation-wheel.html"}]},"12":{"title":"Star Ferry → TST","hours":"Central ↔ Tsim Sha Tsui runs 6:30 AM – 11:30 PM; weekday evenings every 6–8 min until ~8:30–8:40 PM, then every 10–12 min.","cost":"Mon–Fri adult: upper deck HK$5.0, lower deck HK$4.0.","getThere":"Central Star Ferry Pier → Tsim Sha Tsui Star Ferry Pier.","watch":"No eating or drinking on board; sailings can be adjusted for marine traffic and weather.","tips":["Pay by Octopus at the gate, HKD cash (HK$10/HK$20 notes and coins; change given), or QR/credit card at the self-service machines.","Upper deck costs HK$1 more and has the better harbour view."],"sources":[{"label":"Star Ferry: routes, timetable & fares","url":"https://www.starferry.com.hk/en/service"}]},"13":{"title":"TST Waterfront / WinterFest","hours":"Prudential Hong Kong Winter Wonderland in TST: light show 7–11 PM daily (18 Nov 2026 – 5 Jan 2027).","cost":"Free","getThere":"Walk from the TST Star Ferry Pier to the Hong Kong Cultural Centre Viewing Deck.","highlights":["Projection mapping across the Hong Kong Cultural Centre, Museum of Art and Space Museum, set to a northern-lights Christmas concert."],"tips":["Vantage points: the Cultural Centre Viewing Deck, or outside the Museum of Art and Space Museum.","Show schedule is subject to change without notice."],"sources":[{"label":"Discover Hong Kong: Winter Wonderland in Tsim Sha Tsui","url":"https://www.discoverhongkong.com/eng/events/hong-kong-winterfest/winter-wonderland-in-tsim-sha-tsui.html"}]},"15":{"title":"Late Food / Dessert","watch":"Kai Kai's opening hours were not published on the pages checked.","highlights":["Kai Kai Dessert (Michelin-recognised, 40+ years): traditional dessert soups — black sesame, almond, red bean with lotus seeds, tofu skin with ginkgo. G/F, 113-115 Parkes Street, Jordan."],"tips":["No specific late-night arcade or dessert hours could be verified; check live hours on a map app before walking over."],"sources":[{"label":"Discover Hong Kong: Kai Kai Dessert","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kai-kai-dessert.html"}]}}},"day-15":{"checked":"2026-11-11","items":{"0":{"title":"Yat Tung Heen — Michelin-Star Dim Sum Brunch #2","hours":"Sat, Sun & PH: 10:00 AM – 4:00 PM (last order 3:30 PM); 6:00–10:30 PM (last order 9:30 PM). Takeaway 12–9 PM daily.","getThere":"Level B2, Eaton HK, 380 Nathan Road, Jordan, Kowloon.","watch":"Per-dish prices were not readable on the published menus; budget is unverified.","highlights":["One Michelin star every year 2017–2026; Cantonese kitchen led by Chef Tam Tung, in a moody 1920s-Shanghai-tavern dining room.","Signatures on the restaurant's menu page: Signature Honey-glazed Barbecued Pork (char siu), Golden Fried Crispy Chicken Skin and Meat with steamed pancakes, Roasted Suckling Pig.","Menus listed: Dim Sum Set Lunch, Chef's Winter Recommendations, Michelin Degustation 2026."],"tips":["Book via SevenRooms (linked from the restaurant site) or call +852 2710 1093 / 2710 1094; LINE ID yattungheen.","The 'dine-in dim sum lunch deal' is weekday-only — not available on Saturday.","Protein: char siu, roast suckling pig and crispy chicken are the meat-forward anchors."],"sources":[{"label":"Yat Tung Heen: menus, hours & contact","url":"https://www.yattungheen.com/menus"},{"label":"Eaton HK: Food & Drink (Yat Tung Heen)","url":"https://www.eatonworkshop.com/en-us/hong-kong/food-beverage/"}]},"1":{"title":"MTR to Causeway Bay","getThere":"Tsuen Wan Line (red) from Jordan via Tsim Sha Tsui to Admiralty, change to the Island Line (blue) eastbound: Wan Chai → Causeway Bay.","sources":[{"label":"MTR system map & line station lists","url":"https://www.mtr.com.hk/en/customer/services/system_map.html"}]},"2":{"title":"60th Hong Kong Brands & Products Expo — Opening Day","hours":"12 Dec 2026 – 4 Jan 2027 (24 days). 11:00 AM – 9:00 PM daily to 3 Jan; last day 11 AM – 8 PM. No admission in the final 30 min (final hour on the last day).","getThere":"Victoria Park, Causeway Bay.","watch":"Admission fee was not shown on the organiser pages checked.","highlights":["11 themed zones and 900+ outdoor booths (organiser CMA).","Zones include Hong Kong Brands Square, Food & Beverages, Grocery & Noodles, Ginseng/Dried Seafood & Soup Packs, Beauty & Healthcare, Living & Household, Chillax Zone, Food Plaza, Hometown Flavors.","Stage performances, shopping offers and lucky draws."],"tips":["Head for the Food Plaza and Hometown Flavors zones for snacks; Food & Beverages for samples.","Opening day is Saturday Dec 12; the gates open at 11 AM, so an 11:30 arrival is inside hours."],"sources":[{"label":"HKBPE: The 60th Hong Kong Brands and Products Expo","url":"https://www.hkbpe.com.hk/web/subpage.php?mid=102&id=1333&lang=en"},{"label":"CMA: 60th HKBPE announcement","url":"https://www.cma.org.hk/en/"}]},"4":{"title":"Ding Ding Tram West → Wan Chai (20–30 min)","cost":"Adult HK$3.30 flat fare.","getThere":"Board any westbound tram in Causeway Bay (routes to Kennedy Town, Shek Tong Tsui or Western Market) and ride through Wan Chai to Central.","tips":["Pay when you leave by the front exit: Octopus, Visa/Mastercard/UnionPay/JCB/Amex, Apple/Google/Samsung Pay, or QR codes.","Cash goes straight into the coin box — no change on board."],"sources":[{"label":"Hong Kong Tramways: schedules & fares","url":"https://www.hktramways.com/en/schedules-fares/"}]},"6":{"title":"Star Ferry: Wan Chai → TST","hours":"Central ↔ TST Saturday sailings every 6–8 min from ~7:25 AM to ~10:30–10:40 PM.","cost":"Sat, Sun & PH adult: upper deck HK$6.5, lower deck HK$5.6.","getThere":"Walk the Central Harbourfront (AIA Vitality Park, Observation Wheel) to the Central Star Ferry Pier → Tsim Sha Tsui Star Ferry Pier.","watch":"No eating or drinking on board.","tips":["Octopus at the gate, HKD cash (HK$10/HK$20 notes and coins; change given), or QR/credit card at the ticket machines.","Upper deck costs ~HK$1 more and has the better view."],"sources":[{"label":"Star Ferry: routes, timetable & fares","url":"https://www.starferry.com.hk/en/service"},{"label":"Discover Hong Kong: Observation Wheel & AIA Vitality Park","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-the-hong-kong-observation-wheel.html"}]},"9":{"title":"Aqua Luna Evening Harbour Cruise — Tsim Sha Tsui Pier 1","hours":"Evening Harbour Cruise sailings at 4:30, 5:30, 6:30 and 8:30 PM; 45 minutes. Sailings on the half-hour return to your boarding pier.","cost":"Adult HK$280, child (4–11) HK$180; one complimentary drink per ticket.","getThere":"Pick-up points: Tsim Sha Tsui Public Pier 1 and Central Pier 9 (two pick-ups per cruise; check the timetable for the order).","watch":"Tickets are non-refundable. Sailing cancelled if Typhoon Signal No. 3 or Red Rainstorm (or higher) is hoisted; the route may change for weather.","highlights":["Lounge beds on deck; the 5:30 PM sailing catches sunset turning into city lights.","The sunset sailing pairs with an aqualuna Sundowner mocktail."],"tips":["Pick TST Pier 1 as your boarding pier when booking so the 5:30 PM loop returns you to TST.","One free reschedule if requested 12+ hours before departure; within 12 hours HK$50 per person."],"sources":[{"label":"Aqua Luna: Evening Harbour Cruise","url":"https://aqualuna.com.hk/experiences/evening-harbour-cruise/"}]},"11":{"title":"Winter Wonderland in Tsim Sha Tsui","hours":"7–11 PM daily, 18 Nov 2026 – 5 Jan 2027.","cost":"Free","getThere":"Hong Kong Cultural Centre precinct; MTR Tsim Sha Tsui or East Tsim Sha Tsui.","watch":"Show schedule is subject to change without prior notice.","highlights":["Projection mapping on the Hong Kong Cultural Centre, Museum of Art and Space Museum — a Christmas concert inspired by the northern lights."],"tips":["Vantage points: the Cultural Centre Viewing Deck, or outside the Museum of Art and Space Museum."],"sources":[{"label":"Discover Hong Kong: Winter Wonderland in Tsim Sha Tsui","url":"https://www.discoverhongkong.com/eng/events/hong-kong-winterfest/winter-wonderland-in-tsim-sha-tsui.html"}]},"12":{"title":"Arcade / Games — TST Late Night","tips":["No TST arcade's late hours could be verified; confirm on a map app before walking.","Fallback that is verified: the TST harbourfront light show keeps running until 11 PM."],"sources":[{"label":"Discover Hong Kong: Winter Wonderland in Tsim Sha Tsui","url":"https://www.discoverhongkong.com/eng/events/hong-kong-winterfest/winter-wonderland-in-tsim-sha-tsui.html"}]},"13":{"title":"Final Dessert + Harbour","getThere":"Kai Kai Dessert, G/F, 113-115 Parkes Street, Jordan (second branch: G/F, 472 Lockhart Road, Causeway Bay).","watch":"Closing time was not published on the page checked; verify before heading over late.","highlights":["Michelin-recognised, 40+ years of traditional Chinese dessert soups: thick black sesame, almond, red bean with lotus seeds, tofu skin with ginkgo."],"sources":[{"label":"Discover Hong Kong: Kai Kai Dessert","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kai-kai-dessert.html"}]}}},"day-16":{"checked":"2026-11-11","items":{"0":{"title":"Checkout with Luggage","getThere":"Taxi to Kowloon Station (Airport Express). Airport Express Taxi Interchange Offer (18 Sep 2026–17 Sep 2027): show an original same-day taxi receipt of HK$50+ at the Kowloon Station AEL Customer Service Centre for 50% off the Octopus fare (HK$52.5 adult to Airport).","watch":"Taxi offer is Octopus-only (not smart tickets, not combinable with other offers) and must be used immediately after redemption.","tips":["Ask the driver for a printed receipt — photos or screenshots are not accepted; one receipt covers up to 5 people.","If using In-town Check-in, redeem the taxi offer at the Customer Service Centre before entering the In-town Check-in area."],"sources":[{"label":"MTR – Airport Express Taxi Interchange Offer","url":"https://www.mtr.com.hk/en/customer/tickets/ael_taxi.html"}]},"1":{"title":"Kowloon Station Bag Drop","hours":"Cathay Pacific In-town Check-in at Kowloon Station: 6:00 am–3:00 pm. Check in from 24 h up to 90 min before departure, within service hours.","cost":"Free check-in, but entry to the In-town Check-in area deducts the full Airport Express fare: Kowloon–Airport HK$105 (Octopus/contactless/QR) or HK$115 (AEL QR Code Ticket).","watch":"E-passport (electronic travel document) required; codeshares on other airlines excluded. Bags max 145×100×85 cm and 32 kg.","highlights":["Smart Check-in Kiosks print boarding passes and bag tags; then Self Bag Drop: belt, face scan, scan tag, collect claim tag.","No further charge at the platform gate later — the fare was taken at the In-town Check-in gate."],"tips":["Use the SAME Octopus/card for the In-town Check-in gate and the platform gate; MTR caps it at 9 Octopus transactions in between, so pay for Sham Shui Po snacks with a different card.","Cathay confirms a valid Airport Express ticket is needed to use any Hong Kong In-town Check-in."],"sources":[{"label":"MTR – Free In-town Check-in Service","url":"https://www.mtr.com.hk/en/customer/services/complom_checkin.html"},{"label":"MTR – Airport Express ticket types & fares","url":"https://www.mtr.com.hk/en/customer/tickets/tf_index.html"},{"label":"Cathay FAQ – AEL ticket for In-Town Check-In","url":"https://www.cathaypacific.com/cx/en_US/faqs/check-in/online-check-in/do-i-need-a-valid-airport-express-line-ticket-when-accessing-any-hong-kong-in-town-check-in.html"}]},"2":{"title":"Sham Shui Po — Breakfast, Market Streets, Old Kowloon","watch":"Sun Heung Yuen is popular with locals — expect a wait. Kung Wo's golden fish tofu (魚腐) is a signature. Opening hours for these spots were not confirmed on official pages.","highlights":["Apliu Street street market: phone accessories, audio/electrical cables, batteries, film cameras, alarm clocks, second-hand radios and vintage typewriters; haggling expected. Infernal Affairs (2002) audio-shop scene was shot here.","Kung Wo Beancurd Factory, 118 Pei Ho St (since 1960, Michelin-listed 2020): stone-ground silky tofu pudding, beancurd puffs, deep-fried tofu, sugar-free soy milk.","Sun Heung Yuen (Kin Kee), G/F 38 Kweilin St (since 1968): beef-and-egg sandwich — marinated beef fried with egg; +HK$1 to toast."],"tips":["Protein breakfast: Sun Heung Yuen's beef-and-egg sandwich, then Kung Wo for soy milk and fried tofu.","Kung Wo grinds soybeans each morning on a granite stone mill — the retro green-and-white mosaic shop is worth a look."],"sources":[{"label":"Discover Hong Kong – Apliu Street","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-apliu-street.html"},{"label":"Discover Hong Kong – Kung Wo Beancurd Factory","url":"https://www.discoverhongkong.com/eng/place-to-go/travel.guide-kung-wo-beancurd-factory.html"},{"label":"Time Out Hong Kong – Sun Heung Yuen","url":"https://www.timeout.hk/restaurants/sun-heung-yuen"}]},"4":{"title":"Back Toward Kowloon Station","getThere":"MTR Sham Shui Po → Kowloon: check the MTR Trip Planner or MTR Mobile app for the current interchange and time, or take a taxi.","tips":["Each MTR ride on the In-town Check-in Octopus counts toward the 9-transaction limit before you re-enter the Airport Express platform."],"sources":[{"label":"MTR Trip Planner (Sham Shui Po → Kowloon)","url":"https://www.mtr.com.hk/en/customer/jp/index.php?oLabel=Sham%20Shui%20Po&oType=HRStation&oValue=17&dLabel=Kowloon&dType=HRStation&dValue=40"},{"label":"MTR – Free In-town Check-in Service","url":"https://www.mtr.com.hk/en/customer/services/complom_checkin.html"}]},"5":{"title":"Airport Express → HKG","hours":"Kowloon → Airport first train 05:53, last 00:52 (timetable effective 13 Sep 2026); trains about every 10 min.","cost":"Kowloon–Airport adult HK$105 Octopus/contactless/QR, HK$115 AEL QR Code Ticket (already paid at In-town Check-in). Ride Together group tickets: 2 for HK$150, 3 for HK$210, 4 for HK$250.","getThere":"Kowloon → Airport 22 min.","watch":"Bags already checked at Kowloon: at HKG go straight to Departures with boarding passes.","tips":["Group tickets are same-day paper Single Journey Tickets bought at the Customer Service Centre; In-town Check-in entry lists only Octopus, contactless card, QR or AEL QR Code Ticket — confirm with staff before buying."],"sources":[{"label":"MTR – Airport Express timetable & journey times","url":"https://www.mtr.com.hk/en/customer/services/timetable_index.html"},{"label":"MTR – Airport Express ticket types & fares","url":"https://www.mtr.com.hk/en/customer/tickets/tf_index.html"},{"label":"MTR – Ride Together group tickets","url":"https://www.mtr.com.hk/en/customer/tickets/promotions_4persons.html"},{"label":"HKIA – Airport Express","url":"https://www.hongkongairport.com/en/transport/to-from-airport/airport-express.page"}]},"6":{"title":"Cathay Pacific CX840 Non-Stop Flight to JFK","hours":"Scheduled 16:35 HKT → 19:05 EST same day; 15h30 block.","watch":"HKIA notes extra US-required security measures on electronic devices for US-bound flights. Schedule data is third-party; the Cathay app and boarding pass are final.","highlights":["Usually an Airbus A350-900 (e.g., B-LRF, B-LRQ, B-LRT)."],"tips":["Power banks: max two per passenger, carry-on only, no in-flight recharging (HKIA notice, 30 Mar 2026).","Before the gate, have boarding pass and passport ready; e-passport holders aged 7+ can use the e-Security Gates."],"sources":[{"label":"PlaneMapper CX840 schedule & history","url":"https://www.planemapper.com/flights/CX840"},{"label":"HKIA power bank notice","url":"https://www.hongkongairport.com/en/important-notice/index.page?noticeid=1585121172788-1"},{"label":"HKIA Transfer / Transit (security, US-bound measures)","url":"https://www.hongkongairport.com/en/passenger-guide/transfer-transit/index.page"}]}}}};
